/** Original VNDRLY specialist instruction. Numerical cases are educational models,
 * not code acceptance criteria or production procedures. Reviewed 2026-11-07. */
const API='https://www.api.org/products-and-services/individual-certification-programs/certifications/';
const AWS='https://www.aws.org/certification-and-education/professional-certification/';
const ASNT='https://certification.asnt.org/certification/examinations/asnt-ndt-level-ii';
const BCSP='https://www.bcsp.org/';
const AMPP='https://www.ampp.org/education/job-function/coatings-inspectors/coating-inspector-roles-and-responsibilities';
export const programs={};
function add(id, rows, sources, coverage, limitations){
 const lessons=rows.map((r,i)=>({id:`${id}_specialist_${i+1}`,title:r[0],body:r[1],links:[...sources],fileIds:[]}));
 const checks=rows.flatMap((r,i)=>r[2].map((q,j)=>({id:`${id}_specialist_${i+1}_check${j+1}`,lessonId:lessons[i].id,prompt:q[0],answer:q[1],distractors:q.slice(2,5),explanation:q[5]})));
 programs[id]={lessons,checks,review:{sources,coverage,limitations}};
}

add('OG20',[
['Vessel inspection planning and damage hypotheses',`A vessel inspection starts with a defensible equipment boundary. Reconcile the nameplate, manufacturer data report, drawings, material records and modification history. Record design pressure and temperature, minimum design metal temperature where established, weld configuration, heat treatment, corrosion allowance and relief-system interfaces. Separate known values from assumptions. Operating pressure is not a substitute for a documented allowable pressure.

Build a damage hypothesis from material, process chemistry, temperature, stress and time. Wet carbon-steel service may involve general thinning, localized attack or wet-H2S damage; cyclic thermal service introduces a different concern. Examine startup, shutdown and upset history as well as normal operation. Map each credible mechanism to susceptible locations: liquid interfaces, nozzles, injection zones, supports, insulation terminations and welded attachments. A convenient thickness grid can miss a narrow damage zone.

For a separator with water accumulating at the bottom, specify examination of the lower shell and interfaces rather than extrapolating upper-shell readings. If external insulation is damaged near a support, include external corrosion investigation even when internal process corrosion is low. Visual inspection, thickness measurement and crack-sensitive examination answer different questions and should be combined deliberately.

Workshop evidence: produce a marked drawing, mechanism-location table and inspection plan stating method, access, coverage, preparation and limitations. An assessor checks whether each proposed method could detect the hypothesized morphology and whether inaccessible regions remain explicit. Reject a plan that declares inaccessible metal satisfactory or uses entry permission as proof of equipment integrity. This is a planning assessment; actual vessel entry requires the separately established isolation, atmosphere and rescue controls.`,[
['A separator has water pooling at its bottom. Which plan best addresses the mechanism?','Target the lower shell and liquid interfaces with methods suitable for localized loss.','Measure only the upper shell.','Use normal pressure as wall-thickness evidence.','Treat the whole vessel as one uniform reading.','Location follows the corrosive environment; upper-shell measurements cannot establish lower-shell condition.'],
['Which input is necessary before using a material allowable stress?','Verified material and applicable temperature/code basis.','Only the vessel paint color.','The operating company name.','The most recent invoice total.','Allowable stresses depend on material, temperature and the adopted design framework.'],
['An insulated support region cannot be examined. How should it appear in the report?','An explicit coverage limitation with a disposition requirement.','No damage found.','Inspection complete without qualification.','Equivalent to a calibrated reading.','Unexamined areas contain uncertainty, not negative inspection results.']]],
['Corrosion rates, remaining life and measurement uncertainty',`A corrosion rate is a thickness change divided by elapsed time at a comparable location. Keep units visible. A historical reading of 12.0 mm and a current reading of 10.8 mm six years later give a long-term rate of (12.0−10.8)/6 = 0.20 mm/year. If the reading two years ago was 11.4 mm, the short-term rate is (11.4−10.8)/2 = 0.30 mm/year. Investigate the difference rather than automatically selecting the more favorable result. Process change, measurement positioning or accelerated attack may explain it.

For an educational case with an engineering-established required thickness of 8.4 mm, remaining life using 0.30 mm/year is (10.8−8.4)/0.30 = 8 years. This calculation is an extrapolation, not an inspection interval. Applicable code limits, mechanism behavior, reliability of measurements and risk decisions constrain the actual interval. Cracking cannot be managed by assuming the uniform-thinning equation describes its growth.

Thickness records must preserve location, technique, surface condition, temperature correction where applicable, instrument identity and reference checks. A 0.1 mm apparent change with readings each uncertain by ±0.2 mm does not establish a reliable small corrosion rate. Negative apparent corrosion may reflect measurement scatter or deposition; it does not prove that metal has regenerated.

Exercise: compute both rates, explain why the recent rate deserves attention, and propose confirmatory measurements at the same mapped locations. The assessor requires correct arithmetic and a recommendation that separates calculated life from permitted service. A passing worksheet includes assumptions and units and does not extrapolate an average across a local thin area.`,[
['12.0 mm falls to 10.8 mm in six years. What is the long-term rate?','0.20 mm/year','0.50 mm/year','1.20 mm/year','5.00 mm/year','Thickness loss is 1.2 mm; dividing by six years gives 0.20 mm/year.'],
['At 10.8 mm current thickness, 8.4 mm required and 0.30 mm/year, calculated remaining life is:','8 years','3 years','36 years','0.125 years','The remaining margin is 2.4 mm; 2.4/0.30 equals eight years. This is not automatically an inspection interval.'],
['A 0.1 mm apparent loss is smaller than measurement uncertainty. What follows?','Confirm comparability and uncertainty before assigning a precise rate.','Assign exactly 0.1 mm/year regardless of elapsed time.','Declare the instrument unusable in all applications.','Assume no corrosion exists anywhere.','Small differences may reflect measurement scatter; repeatability and location matter.']]],
['Pressure, stress and wall calculations',`Pressure creates membrane stresses in a cylindrical shell. In a thin-wall educational model, circumferential stress is approximately PD/(2t), where pressure P and stress use consistent units, diameter D and wall thickness t use the same length unit, and end effects and local stress concentrations are excluded. Longitudinal membrane stress is approximately PD/(4t). The hoop stress is therefore about twice the longitudinal value for this simplified geometry.

At P = 1 MPa, D = 1000 mm and t = 10 mm, hoop stress is approximately 50 MPa. Reducing wall thickness to 8 mm increases it to 62.5 MPa at the same pressure. These relationships explain why wall loss matters; they are not the API/ASME acceptance equations. Actual calculations depend on the applicable shell/head equation, radius convention, weld joint efficiency, material allowable stress, temperature, corrosion allowance, static head and other loads.

For another educational model, t = PR/(SE−0.6P), with supplied values P = 1 MPa, R = 500 mm, S = 100 MPa and E = 1, yields 500/99.4 = 5.03 mm before any separately required allowances. The equation is supplied for arithmetic practice, not asserted applicable to every vessel. Reducing E to 0.85 raises this model result to 5.92 mm. Never assume joint efficiency from appearance.

The calculation assessment requires identifying the supplied equation's validity conditions, checking units, calculating independently and listing omitted loads. External-pressure buckling, heads, nozzles and local thin areas need their own rules. A competent submission explicitly refuses to turn this simplified result into an unrestricted maximum allowable working pressure.`,[
['Using PD/(2t), P=1 MPa, D=1000 mm and t=10 mm gives:','50 MPa','100 MPa','5 MPa','500 MPa','1000 divided by 20 is 50; compatible length units cancel.'],
['In the supplied t=PR/(SE−0.6P) model, lowering E while holding other inputs constant does what?','Increases required thickness.','Decreases required thickness.','Leaves thickness unchanged.','Eliminates pressure loading.','A smaller denominator produces a larger required thickness.'],
['Why cannot the thin-wall hoop equation establish the whole vessel rating?','It excludes other component rules, loads and applicability limits.','Pressure has no relation to stress.','Thickness never affects rating.','Only the name of the inspector establishes rating.','A simplified membrane model does not evaluate heads, nozzles, external pressure or the governing code requirements.']]],
['Welding, heat treatment and examination strategy',`A repair weld joins materials while changing their thermal history. The welding procedure specification gives production instructions; the procedure qualification record records the test variables and results supporting a qualified procedure where required; the welder performance record establishes the individual's qualified range. A qualified welder does not make an unsupported procedure acceptable, and an acceptable procedure does not qualify every welder.

Review base-metal identification, thickness, filler selection, joint preparation, preheat/interpass controls, heat input where controlled, postweld heat treatment and examination requirements before fabrication. Hydrogen-assisted cracking needs attention to susceptible microstructure, hydrogen and tensile stress. Moisture control and preheat may reduce risk under an approved procedure, but arbitrary heating is not a substitute for metallurgical review.

Match examination to likely flaws. Visual inspection finds accessible surface conditions and dimensional deviations. PT targets surface-breaking flaws on suitable nonporous surfaces. MT requires ferromagnetic material. UT and RT have different orientation, geometry and access limitations. A rounded volumetric indication and a planar lack-of-fusion indication need different interpretation even if their apparent lengths match.

A repair pack exercise supplies a carbon-steel vessel, WPS revision B, a welder record for a different process and an NDE report referring to weld 14 instead of weld 41. The learner must identify both qualification and traceability failures before accepting the pack. The assessor retains the comparison table and marked weld map. Critical errors include substituting a procedure without approval, inferring acceptance from a smooth surface, or silently changing the NDE weld identifier. Required acceptance clauses and examination extent must come from the actual adopted standards.`,[
['Which record establishes the person’s qualified welding range?','Welder performance qualification record.','Only the equipment invoice.','Only the PQR.','Only the vessel pressure gauge.','The performance record concerns the welder; a PQR supports procedure qualification.'],
['Which method requires ferromagnetic material?','Magnetic particle testing.','Liquid penetrant testing.','Visual testing.','Radiographic testing.','MT relies on magnetic flux leakage in a suitably magnetized ferromagnetic material.'],
['An NDE report names weld 14 while the repaired weld is 41. What is required?','Traceable reconciliation before using the result for weld 41.','Assume the numbers were transposed and sign.','Delete the report.','Apply the result to every weld on the vessel.','The evidence must identify the actual inspected weld; plausible similarity cannot establish traceability.']]],
['Repair, alteration, rerating and pressure testing',`Distinguish restoring a component from changing its design basis. Replacing damaged material to an approved original configuration may be a repair, while a new nozzle, changed material, higher pressure or changed temperature can require alteration or rerating review. Classification depends on the governing rules, jurisdiction and actual scope, not the contractor's invoice label. Establish the authorized inspector, engineer and repair organization responsibilities before work.

A pressure test checks defined pressure-boundary behavior under specified conditions. It does not independently prove resistance to every future mechanism, and it does not replace required weld examination. The approved plan establishes test pressure, metal temperature, medium, boundaries, temporary connections, calibrated instrumentation, overpressure protection, exclusion and restoration. Pneumatic testing generally introduces substantially more stored energy than a comparable liquid-filled test and needs its own justified safeguards.

Static head matters. With water density taken as 1000 kg/m³, elevation difference 10 m and g = 9.81 m/s², pressure at the lower point is approximately 98.1 kPa greater than at the upper point. A gauge at the top therefore does not show the pressure at the bottom. This arithmetic does not select a test pressure.

Workshop task: review a proposed nozzle alteration with only a leak-test certificate. Produce the missing design, qualification, examination and test/restoration evidence list. The assessor checks that the learner identifies the changed design boundary and hydrostatic head, and does not prescribe an unsupported production test. Final release requires actual results and authorized disposition, not merely an approved plan.`,[
['A new nozzle changes the pressure boundary. What must happen first?','Classify and engineer the change under the applicable alteration requirements.','Call it maintenance to avoid review.','Use the last leak test as approval.','Increase the relief setting immediately.','A new pressure-boundary feature may alter stresses and design requirements; classification precedes execution.'],
['With water, a point 10 m lower has approximately how much greater static pressure?','98.1 kPa','9.81 Pa','981 MPa','Zero','rho*g*h = 1000*9.81*10 Pa = 98.1 kPa.'],
['What does an approved test plan prove?','The planned method has been reviewed, not that the test passed.','The test has already passed.','All future corrosion is prevented.','Every weld is free of flaws.','Approval and performance are separate states requiring separate evidence.']]],
['Code navigation and integrated vessel disposition',`An inspector must identify the applicable document before finding a favorable paragraph. Separate the original construction code, in-service inspection code, jurisdictional requirements, owner specifications and any fitness-for-service methodology. Record edition/addenda and the exact equipment scope. For examination preparation, the API publication effectivity sheet identifies the examination-window references; a newer publication is not automatically the exam reference.

Use a repeatable navigation sequence: classify the component and decision; find scope and definitions; locate the applicable calculation or inspection rule; review exceptions and cross-references; record inputs and conclusion. A table entry without its notes can be wrong. An inspection interval provision cannot be used to waive an immediate unacceptable condition.

Capstone: a vessel has 10.8 mm measured wall, engineering-established required thickness 8.4 mm, recent corrosion rate 0.30 mm/year, an unexamined support and a proposed pressure increase. The eight-year arithmetic remaining life addresses only the supplied thinning model. It neither disposes of the unexamined support nor approves the pressure increase. The correct package separates current-condition evaluation, supplementary inspection and rerating analysis.

Assessment requires a marked vessel drawing, thickness/rate worksheet, source register, uncertainty log and signed recommendation distinguishing acceptable evidence from open decisions. Score identity/traceability, mechanism selection, calculations, governing-rule navigation and disposition separately. Each must be satisfactory; incorrect units, invented joint efficiency or approving an unresolved pressure boundary is a critical failure requiring remediation and reassessment. Passing this original VNDRLY assessment documents the taught knowledge and casework; API eligibility, examination and authorized field practice remain separate.`,[
['Which edition should an API candidate use for an examination window?','The editions identified in that window’s effectivity sheet.','Always the newest publication available.','Any edition with the same cover color.','The oldest edition used by their employer.','Exam references are window-specific and can differ from the newest published standard.'],
['Does eight years of calculated thinning life approve a pressure increase?','No; rerating and other unresolved conditions require separate evaluation.','Yes, for eight years.','Yes, if the exterior paint is intact.','Yes, if the operator signs a training attendance sheet.','The calculation addresses a specific thickness margin and assumed rate, not a changed design envelope.'],
['A favorable table value conflicts with a limiting table note. What controls the analysis?','Read and apply the note and governing scope with the table.','Ignore notes because numbers are more precise.','Choose the less restrictive value automatically.','Average the note and the value.','Tables must be applied with their notes, exceptions and scope.']]]
],[API+'api510'],['Six vessel-specific lessons: damage mapping, rate/life arithmetic, pressure/stress models, welding/NDE, alteration/testing and integrated disposition. Existing G70/G72/G77 supply supporting coordination concepts.'],['Not a complete API 510 examination preparation course: licensed construction/in-service code clauses, all head/nozzle/external-pressure calculations and an edition-by-edition objective crosswalk are not supplied. Numerical examples are explicitly limited educational models. Actual inspector eligibility, examination and field authorization remain external.']);

add('OG21',[
['Piping circuits and location-specific damage',`A piping inspection circuit groups components with sufficiently similar material, process environment and damage behavior to support a coherent plan. It is not merely everything carrying the same line number. Map pressure, temperature, phases, chemistry, flow regime, material changes and past failures. Circuit boundaries should change when these factors change enough to alter expected damage.

Injection points and mixing zones can experience concentrated chemistry or thermal gradients. Dead legs may collect water or deposits despite little flow. Soil-to-air interfaces, supports and damaged insulation create external-corrosion opportunities. Elbows, reducers and impingement locations may have erosion-corrosion. Small-bore branches can suffer vibration fatigue even when main-line thickness is satisfactory. These locations justify targeted examination rather than uniformly spaced convenience readings.

Consider a hot hydrocarbon line receiving a water-based additive. Downstream mixing can produce a local corrosive environment absent upstream. A branch normally isolated by a valve still contains stagnant fluid; marking it inactive does not remove it from the integrity system. Build a separate hypothesis for each region and identify the upstream/downstream extent requiring examination under the approved plan.

Workshop: mark an isometric with circuit boundaries, condition-monitoring locations, dead legs, injection zones, supports and access limitations. For every location, explain the mechanism and method selection. The assessor rejects a plan that averages a damaged elbow into a long straight-run thickness, omits a dead leg, or treats piping class as proof of actual material. The output is an inspection plan with explicit boundaries, not a field authorization.`,[
['What is a sound basis for inspection-circuit boundaries?','Similar material, process conditions and expected damage mechanisms.','Equal lengths on a drawing.','One paint color throughout the plant.','The same contractor invoice.','Circuits support mechanism-based inspection; geometrical convenience alone is insufficient.'],
['Why inspect a normally isolated dead leg?','Stagnant liquid or deposits can create localized corrosion.','Isolation permanently removes all fluid.','No flow guarantees no degradation.','Its thickness equals the main run by definition.','Dead legs may retain corrosive phases despite low flow.'],
['Main-line thickness is satisfactory but a small branch vibrates. Which concern remains?','Fatigue cracking at the branch connection.','Only uniform corrosion in the main run.','No concern because the main line passed.','Only nameplate readability.','Vibration-induced cyclic stress can damage a branch independently of main-line thinning.']]],
['Piping wall loss and remaining-life calculations',`Compare measurements at traceable locations using a consistent technique. Suppose a pipe location measured 7.8 mm five years ago and now measures 6.8 mm. Long-term loss is 1.0 mm, so the rate is 0.20 mm/year. If it measured 7.4 mm two years ago, the recent rate is 0.30 mm/year. The higher recent rate may reflect process acceleration, but first verify location and measurement comparability.

With an engineering-established required wall of 4.7 mm, the current margin is 2.1 mm. At 0.30 mm/year, the arithmetic remaining life is seven years. Do not label that result the inspection interval. Applicable classification, code maxima, mechanism uncertainty and approved RBI decisions may require earlier work. A local groove or crack cannot be accepted by averaging it with sound adjacent metal.

Nominal schedule thickness is a purchasing designation, not measured current thickness. Manufacturing tolerance and corrosion allowance are distinct concepts. When selecting replacement pipe, the code calculation must address required pressure thickness, allowances and applicable manufacturing tolerance. Do not subtract corrosion allowance twice or use a nominal wall as if it were a guaranteed minimum.

Exercise: prepare a three-date trend and a sensitivity case at 0.40 mm/year. The latter gives 2.1/0.40 = 5.25 years, showing how a plausible rate change affects planning. Record assumptions and identify what additional process history or examination would reduce uncertainty. An assessor verifies units, location identity and the distinction between a screening life calculation and an authorized continued-service decision.`,[
['7.8 mm becomes 6.8 mm in five years. Rate equals:','0.20 mm/year','1.00 mm/year','5.00 mm/year','0.02 mm/year','One millimetre divided by five years is 0.20 mm/year.'],
['At 6.8 mm current, 4.7 mm required and 0.30 mm/year, remaining life is:','7 years','2.1 years','22.7 years','0.7 years','The 2.1 mm margin divided by 0.30 mm/year gives seven years.'],
['Can nominal schedule thickness replace a current UT reading?','No; it describes a nominal product dimension, not current condition.','Yes, if the pipe is painted.','Yes, if purchased recently.','Yes, if the schedule number is large.','Actual wall can vary due to manufacturing tolerance and service loss.']]],
['Pressure thickness, components and flange ratings',`For arithmetic training, use the supplied straight-pipe model t = PD/[2(SEW+PY)]. With P = 2 MPa, outside diameter D = 200 mm, S = 100 MPa, E = 1, W = 1 and Y = 0.4, t = 400/[2(100+0.8)] = 1.984 mm. Add a supplied 1.5 mm allowance to obtain 3.484 mm. If a supplied negative manufacturing tolerance is 12.5%, a nominal selection must satisfy nominal ×0.875 ≥3.484; the resulting minimum nominal value is approximately 3.982 mm before selecting an available suitable product.

This is a deliberately supplied exercise, not an assertion that the equation or factors apply to every service. Actual applicability includes code edition, material, temperature, geometry and range limits. Bends, branch reinforcement, threaded regions, external loads, flexibility and special service may require additional checks. Pressure-only arithmetic does not assess all piping stresses.

A flange class is not a pressure value in psi. Allowable pressure depends on material group, temperature and the adopted rating table. A Class 150 marking cannot be interpreted as universally safe at 150 psi or any other fixed value. The assembly includes bolts, gasket, facing, valve and connections; incompatible components can defeat an otherwise adequate flange selection.

The assessment provides a fictional rating table and component list. The learner must choose the correct material/temperature row, identify the lowest applicable assembly limitation and preserve table notes. Incorrect diameter convention, omitted tolerance or assuming class equals pressure is a critical arithmetic or interpretation error.`,[
['The supplied pressure-only calculation gives 1.984 mm and allowance is 1.5 mm. Total before tolerance is:','3.484 mm','0.484 mm','2.976 mm','1.984 mm','The allowance is added to the calculated pressure thickness.'],
['A required minimum is 3.484 mm and negative tolerance is 12.5%. Minimum nominal is about:','3.982 mm','3.049 mm','3.609 mm','27.872 mm','Divide by 0.875 because the delivered minimum may be only 87.5 percent of nominal.'],
['What does Class 150 mean for flange pressure selection?','Use the applicable material-temperature rating table and notes.','The flange always permits exactly 150 psi.','The flange always permits 150 MPa.','Temperature does not matter.','Pressure-temperature ratings depend on the actual standard and material, not just the class number.']]],
['Welding repairs and temporary interventions',`A repair plan begins with the defect mechanism and the affected boundary. Replacing a spool removes damaged material but introduces new welds, supports, alignment and testing requirements. A welded attachment or sleeve can redistribute stress or create an inaccessible corrosion region. A temporary repair is an engineered, time-bounded disposition, not permission to defer indefinitely.

Review WPS and welder scope, material traceability, fit-up, heat treatment, examination and pressure/leak-test requirements before installation. A change from one welding process to another may affect procedure and personnel qualifications. A repair on a line with environmental cracking cannot be justified solely by a thickness calculation. The repaired location and adjacent susceptible material need the mechanism addressed.

In a synthetic case, a carbon-steel spool is replaced with an alloy spool because it is available. Higher purchase cost does not establish compatibility. Thermal expansion, weldability, galvanic behavior, pressure-temperature properties and process chemistry require review. The correct action is a controlled material substitution decision, not unilateral installation.

Assessment uses an offline repair dossier with an expired temporary-repair date, missing filler traceability and incomplete NDE coverage. The learner lists each discrepancy, the technical consequence and the required owner/engineering disposition. The assessor requires a proposed completion plan that includes restoration of supports and insulation, updated isometric and next inspection requirements. No live leak sealing, welding on pressurized piping or unsupported clamp selection is taught or authorized by this case.`,[
['What makes a temporary repair acceptable as a managed condition?','An approved engineered basis, defined limits and a tracked expiry or review date.','Calling it temporary on an invoice.','A photograph of the clamp.','An indefinite inspection deferral.','Temporary repairs require controlled conditions and a defined continuing-management obligation.'],
['A higher-cost alloy spool is available. Can it replace carbon steel without review?','No; compatibility and design implications must be assessed.','Yes, higher cost proves suitability.','Yes, every alloy has identical expansion.','Yes, if dimensions match externally.','Material changes affect welding, thermal behavior, corrosion and ratings.'],
['Which repair completion item is easy to miss but technically relevant?','Restored supports and updated inspection records.','Only contractor payment.','Only a new paint color.','Only deleting the old defect record.','Support condition affects loads, and records must reflect the actual installed configuration.']]],
['Testing, static head and reinstatement',`A piping test boundary must include every connected item actually exposed to test pressure. Show blinds, test manifolds, instruments, vents and excluded equipment on a controlled drawing. A closed valve symbol does not independently establish adequate isolation. The approved procedure addresses medium compatibility, temperature, pressure ramp, hold, acceptance, depressurization and emergency response.

Static head changes pressure with elevation. For water, a low point 20 m below a high-point gauge experiences about 196.2 kPa additional pressure. When a high point needs a specified minimum pressure, verify that low points and connected components remain within their permitted limits. The test engineer must resolve any conflict; inspectors should not simply move the gauge to obtain a favorable reading.

Record calibration identities, actual pressure/temperature/time history, leaks and repairs. Temperature changes can affect a closed-system pressure trace; a pressure decline requires evaluation, not automatic acceptance or automatic diagnosis of a leak. Pneumatic tests demand their distinct stored-energy controls. A test certificate with no boundary cannot prove which branch was tested.

Reinstatement is a separate verified stage. Remove temporary items through the approved process, restore relief devices and instruments, confirm valve positions and complete leak-tightness or functional checks required by the plan. In the practical desk exercise, an assessor plants an omitted branch and a relief device left isolated. Both must be identified. Evidence comprises the marked boundary, test record review and independently checked reinstatement list.`,[
['A water-filled low point is 20 m below the gauge. Additional pressure is about:','196.2 kPa','19.62 Pa','2 MPa','Zero','1000*9.81*20 Pa equals 196.2 kPa.'],
['A test certificate lacks the tested boundary. What is missing?','Evidence establishing which components the result covers.','Only a decorative diagram.','Proof that water exists.','The training attendance list.','Boundary traceability is necessary to apply a result to specific piping.'],
['A successful test is complete, but a relief device remains isolated. Is operating release established?','No; reinstatement and protection must be verified.','Yes, pressure testing authorizes all valve positions.','Yes, if the test gauge is removed.','Yes, if the line number is correct.','Test success does not establish that normal protective functions have been restored.']]],
['Piping capstone and code-based reporting',`The final report links each conclusion to equipment identity, condition, applicable criteria and authorized disposition. Separate observed data from inferred mechanism, calculated prediction and acceptance. Include isometric revision, circuit and monitoring-location identifiers, technique/coverage, current thickness, prior comparable values, calculated rates, required-thickness basis, limitations and the next action.

In the capstone, the main run has seven years of calculated thinning life, a branch has vibration indications, and an injection point has no recent coverage. The correct disposition is not a single green line-status icon. The main-run calculation is retained with its assumptions; branch fatigue and injection-zone uncertainty need their own examination and engineering decisions. A maximum code interval cannot waive a known unresolved condition.

Practice navigating an owner-supplied licensed reference: find the circuit classification, inspection requirements, repairs and rating provisions relevant to this exact case; record edition, paragraph and exception. If the reference is unavailable, identify the missing decision basis instead of fabricating a clause. API 570 examination references are tied to the examination window, so preparation should use the corresponding effectivity sheet.

An assessor evaluates a complete dossier for five outcomes: accurate circuit boundaries, correct arithmetic, mechanism-sensitive method selection, traceable rule application and defensible disposition. Every outcome must pass. Concealing missing coverage, approving unsupported rerating or replacing a reading with a nominal dimension is a critical failure. Retain first-attempt work, feedback and corrected independent work as distinct records.`,[
['A main-run life calculation is favorable but an unexamined injection zone remains. What is correct?','Keep the calculation bounded and address the injection zone separately.','Apply the main-run life to every component.','Delete the injection location from the circuit.','Assume additives prevent corrosion.','Different local mechanisms and missing coverage cannot be resolved by another location’s calculation.'],
['What should a required-thickness value in the report identify?','Its engineering/code basis and applicable inputs.','Only a rounded number.','Only the nominal schedule.','Only the contractor name.','A number without its basis cannot be independently checked or applied to changed conditions.'],
['When a governing clause is unavailable, the learner should:','Identify the unresolved decision and obtain the actual reference.','Invent a plausible paragraph number.','Treat the absence as permission.','Copy an unrelated tank rule.','Honest incompleteness preserves the boundary; fabricated references create false acceptance.']]]
],[API+'api570'],['Six piping-specific lessons with circuit mapping, rate/life and pressure/tolerance calculations, flange interpretation, repair dossiers and test/reinstatement exercises.'],['Licensed API 570/574 and construction-code rules are not reproduced. Full examination-window BOK coverage, flexibility/branch calculations, actual owner classifications and practical inspector qualification remain unverified.']);

add('OG22',[
['Tank components, load paths and deterioration',`An aboveground storage tank transfers liquid load through its shell, bottom and foundation. Identify shell courses, horizontal and vertical seams, bottom and annular plates where present, roof structure, nozzles, reinforcement, anchorage and foundation. A floating roof introduces seals, drains, pontoons and travel clearances; a fixed roof introduces its own support and venting arrangements. Inspect the actual tank type rather than applying one generic checklist.

Hydrostatic pressure increases with liquid depth. For a liquid density of 850 kg/m³ and depth 12 m, bottom pressure is rho*g*h = 850*9.81*12 = 100062 Pa, about 100 kPa. The upper shell sees less liquid head than the lower shell. This explains why shell-course thickness and location matter. Changing stored product density or permitted fill height can change loading even without a pressure-vessel-style operating pressure increase.

Separate product-side corrosion from soil-side bottom corrosion. Water bottoms, deposits and microbial activity may create localized attack; drainage and foundation conditions influence underside damage. Roof drain failure can add load to a floating roof. Blocked venting can create pressure or vacuum conditions the tank was not designed to sustain.

Exercise: mark the load path and damage locations on a tank sketch. The assessor requires a distinct rationale for shell, bottom, roof and foundation examinations. Missing underside coverage must remain visible. A routine exterior walkdown cannot establish bottom integrity or justify a higher fill level.`,[
['At density 850 kg/m³ and depth 12 m, bottom liquid pressure is approximately:','100 kPa','10 MPa','850 Pa','12 kPa','rho*g*h gives about 100062 Pa, which is 100 kPa.'],
['Changing to a denser product at the same fill height does what?','Increases hydrostatic shell loading.','Leaves all loading unchanged.','Reduces bottom pressure.','Eliminates the need for venting.','Liquid pressure is proportional to density at the same depth.'],
['Which inspection conclusion is unsupported by an exterior walkdown alone?','The entire tank bottom is sound.','Exterior corrosion is visible at a support.','A roof drain component is damaged.','A nameplate is illegible.','The bottom and its underside require appropriate coverage beyond an exterior visual walkdown.']]],
['Shell evaluation and fill-height reasoning',`Shell evaluation connects measured condition to an approved required-thickness basis for each course and loading condition. Do not combine readings from different elevations into one average and assume the result represents the most highly loaded region. Local thin areas, pits and weld conditions require their applicable evaluation rules rather than arbitrary averaging.

For teaching only, a thin-cylinder liquid-head model gives hoop stress sigma = rho*g*h*D/(2t). With rho = 1000 kg/m³, h = 10 m, D = 20 m and t = 0.010 m, sigma is 98.1 MPa. If thickness falls to 0.008 m, this model gives 122.6 MPa. All lengths must be converted consistently. This model omits actual tank-code factors, course-specific formulas, joints and local conditions and cannot establish a field fill limit.

If engineering has independently established required thickness 7.0 mm, measured thickness is 9.0 mm and a defensible uniform rate is 0.25 mm/year, arithmetic life is eight years. The rate and required thickness must correspond to the same location and service. A planned switch to a heavier product invalidates assumptions that depend on density.

Assessment: calculate the two model stresses and remaining life, then list why neither alone establishes an allowable operating level. The assessor checks course identity, units, density assumptions and treatment of local damage. The accepted deliverable is a bounded worksheet and a request for the actual code evaluation, never an improvised tank rerating.`,[
['In the supplied shell model, reducing wall from 10 to 8 mm changes stress by what factor?','1.25','0.80','2.00','0.20','Stress is inversely proportional to thickness, so 10/8 = 1.25.'],
['9.0 mm current, 7.0 mm required and 0.25 mm/year gives:','8 years','2 years','28 years','36 years','The 2 mm margin divided by 0.25 mm/year gives eight years.'],
['Why must a product-density change trigger review?','It changes liquid-head loading and may change corrosion conditions.','It changes only the label on the tank.','Every liquid has the same density.','It automatically repairs shell thinning.','Both mechanical and chemical service assumptions can change.']]],
['Bottom inspection, mapping and leak prevention',`Tank-bottom inspection needs a coordinate system that survives future outages. Map plate identifiers, welds, sumps, columns, repairs and reference directions. Describe inspected area and exclusions around obstructions. Magnetic-flux-leakage scanning can screen suitable ferromagnetic bottoms for metal loss, but sizing, near-weld zones, surface condition and tool capabilities must be addressed. Confirmatory UT provides local thickness evidence under the approved technique; it does not retroactively fill every unscanned area.

Distinguish general thinning, isolated pits and connected localized corrosion. A plate average can conceal a deep pit. Determine whether reported metal loss is product-side or underside where the method supports that distinction, and state ambiguity otherwise. Vacuum-box examination of suitable welds addresses leakage paths under the specified procedure, not the entire remaining wall of the bottom.

In a synthetic outage, 90% of the floor is screened and several column areas are inaccessible. The report must state actual coverage, confirm sizing of relevant indications and assign the excluded areas a technical disposition. An owner cannot infer 100% bottom acceptance by multiplying the inspected area by a favorable average thickness.

Practical assessment uses a clean training plate or data set containing mapped artificial loss and a weld leak indication. A qualified assessor checks instrument setup under the supplied procedure, accurate coordinates, correct confirmation decisions and bounded reporting. Fabricating readings or changing the coverage percentage is a critical failure. Actual entry and work conditions require their own permits and controls.`,[
['A bottom scan covers 90%. What can its negative result support?','A bounded conclusion for the actually examined area and technique.','No loss anywhere in the tank.','Automatic acceptance of the unscanned 10%.','Proof that all welds are leak-tight.','Coverage and method limitations bound the conclusion.'],
['Why retain plate coordinates for a deep indication?','To locate, confirm and compare the same area later.','Only to decorate the report.','To replace calibration.','To avoid measuring its depth.','Repeatable location is necessary for confirmation, repair and trending.'],
['A vacuum-box weld test primarily addresses:','Leakage through the tested weld region under the procedure.','Every underside corrosion pit.','Shell tensile strength.','All future settlement.','Leak testing and wall-loss measurement are different inspection questions.']]],
['Settlement, distortion and brittle-fracture screening',`Settlement is not a single number. Uniform settlement lowers the whole tank; planar tilt rotates its overall plane; differential settlement distorts the shell or bottom; localized edge settlement creates concentrated deformation near the shell-bottom region. These shapes have different effects on stresses, drains, roof travel, piping connections and seals. Use stable survey references and a consistent coordinate convention.

Suppose opposing shell points 20 m apart differ in elevation by 40 mm. The simple slope is 0.040/20 = 0.002, or 0.2%. This describes tilt, not acceptability. A third point departing sharply from the best-fit plane may reveal differential distortion that the two-point slope conceals. Compare complete profiles under the actual tank standard and engineering method.

Brittle fracture involves material toughness, temperature, thickness, stress and flaws. An older tank with incomplete material records requires more than a warm-weather visual inspection before cold-service changes or major repairs. Hydrostatic testing can be an important event in the evaluation, but arbitrary cold testing is not a remedy. The engineering basis must address material and temperature restrictions.

Assessment provides eight survey points, a localized outlier and a proposed cold-service change. The learner distinguishes tilt from local distortion, computes the simple slope and identifies missing toughness/material evidence. The assessor rejects any claim that a small average slope proves every local condition acceptable or that an undocumented material can be assigned a convenient toughness value.`,[
['40 mm difference across 20 m gives slope:','0.2%','2%','20%','0.002%','0.040/20 = 0.002; multiplying by 100 gives 0.2 percent.'],
['A local point departs markedly from the overall tilted plane. What remains to evaluate?','Differential or localized settlement effects.','Only uniform settlement.','Nothing because average tilt is small.','Only coating color.','A best-fit plane can conceal local distortion and associated stress.'],
['Which combination matters to brittle-fracture susceptibility?','Material toughness, temperature, stress, thickness and flaws.','Only tank capacity.','Only roof color.','Only the last inspection date.','Brittle fracture depends on interacting material, loading and flaw conditions.']]],
['Tank repairs, welding and reconstruction controls',`A tank repair plan identifies the damaged component and the requirements for its restored condition. Bottom patches, shell inserts, nozzle changes and roof repairs have different geometry, weld and examination issues. Reconstruction adds identification and reassembly controls for reused material. Do not assume a method acceptable for a roof plate also suits a shell course or annular region.

Before work, confirm material identity, approved drawings, WPS/PQR basis, welder scope, joint preparation, dimensional tolerances, weld sequence and examination requirements. Repair geometry can create stress concentrations or interfere with drainage and future inspection. The technical authority must evaluate the actual design rather than accept a patch merely because it covers the visible damage.

Inspection hold points should occur while features remain accessible: material receipt, fit-up, root/back-gouge stages when applicable, completed weld examination and final dimensional checks. Leak testing, NDE and hydrostatic-test requirements come from the adopted standard and authorized engineering decision. A waiver requires its actual documented basis, not a scheduling preference.

In the assessment dossier, an insert plate has traceability but the welder record covers a different process, and final NDE omits a seam intersection. The learner must keep these as separate unresolved conditions. The assessor requires marked drawings, qualification comparison and a completed/held inspection-point register. A repair cannot be released merely because every purchased material certificate is present; workmanship and examination evidence must also be complete.`,[
['Can a roof patch detail automatically be used on the lower shell?','No; loading, geometry and governing requirements differ.','Yes, all tank plates have identical duty.','Yes, if both are carbon steel.','Yes, if the patch is larger.','Different tank components carry different loads and have different repair rules.'],
['When should a hold point for an inaccessible root condition occur?','Before subsequent work hides that condition.','Only after the tank returns to service.','Only at final invoicing.','Never if the final bead looks smooth.','Inspection must occur while the feature can actually be examined.'],
['Material certificates are complete but a weld intersection lacks required NDE. Status is:','Examination incomplete; acceptance remains unresolved.','Fully accepted.','Automatically acceptable because material is correct.','A documentation-only issue with no technical consequence.','Material identity does not establish weld soundness or complete required coverage.']]],
['Tank inspection plan and capstone dossier',`An integrated tank plan separates routine in-service observations, external inspections, thickness work and internal outage examinations. The applicable intervals depend on the adopted code, service, corrosion basis, bottom safeguards, inspection history and any qualified risk-based methodology. Do not manufacture a universal interval from one thickness calculation.

Capstone: a tank changes from a lighter product to water service, has an eight-year arithmetic shell life under the old assumptions, incomplete bottom coverage and a settlement outlier. The learner must revisit liquid-head loading, changed corrosion environment, bottom uncertainty and settlement independently. A favorable shell trend cannot dispose of the bottom or foundation.

The final dossier contains a component register, drawings, thickness and settlement maps, calculations with assumptions, repair/NDE records, applicable reference editions, limitations and proposed actions. For each conclusion, state whether it is measured, calculated, inferred or accepted by the responsible authority. Preserve superseded conclusions with their revision history so future inspectors understand why the operating envelope changed.

Assessment criteria are component/load understanding, correct calculations, inspection-method coverage, settlement reasoning and traceable disposition. All five must be satisfactory. Unsupported fill-height approval, invented bottom readings or ignored local settlement is a critical failure. The course supplies original knowledge and casework; it does not supply every licensed API 653/API 650 calculation, a complete examination crosswalk or an API credential. Actual tanks require qualified inspectors and engineering decisions using their records and governing requirements.`,[
['A lighter-product tank will store water. Which assumption must be revisited?','Hydrostatic loading and service-related degradation.','Only the product-name field.','No assumptions if the tank diameter stays the same.','Only the training expiry date.','Density and chemical/environmental conditions can both change.'],
['Can a favorable shell rate resolve an unexamined bottom?','No; the bottom requires its own evidence and disposition.','Yes, steel corrodes equally everywhere.','Yes, if the roof is fixed.','Yes, if the tank is cylindrical.','Shell and bottom environments, mechanisms and coverage differ.'],
['Why keep superseded inspection conclusions?','To preserve the basis and history of changed decisions.','To count them as new inspections.','To conceal current results.','To substitute them for missing new data.','Revision history supports traceable integrity management without misrepresenting old evidence as current.']]]
],[API+'api653'],['Tank-specific load/head arithmetic, shell trends, bottom screening/confirmation, settlement, repairs and integrated assessment.'],['Full API 653/API 650 equation sets, licensed acceptance tables, exact examination-window mapping and actual survey/NDE practical delivery remain outside the supplied content.']);

add('OG23',[
['Inspection authority and construction quality planning',`A pipeline construction inspector verifies work against approved requirements and records deviations. The inspector does not redesign the line from personal preference or silently change acceptance criteria. Establish the contract hierarchy, approved drawings, specifications, permits, applicable regulatory scope and the inspector's delegated hold/release authority. Distinguish observation, witness point, hold point and nonconformance disposition in the project plan.

An inspection and test plan places checks before irreversible concealment. Typical stages include material receipt, right-of-way controls, excavation, bending, welding, NDE, coating, lowering-in, backfill, testing and restoration. Each checkpoint needs a criterion, responsible party, required evidence and release authority. A hold point cannot be cleared by attendance alone.

Daily reports should identify location by station/chainage and coordinates where required, date/time, weather, crew, work performed, inspected quantity, findings and outstanding issues. Separate direct observations from contractor statements. A photograph needs location, orientation and scale when used for dimensional evidence. Preserve original records and corrections rather than backdating a clean report.

In an exercise, a contractor wants to backfill a coated joint before holiday-test results arrive. The learner identifies the applicable hold point, records the affected location and prevents concealment through the authorized process. The assessor requires an inspection record, a nonconformance description and a release decision tied to evidence. The goal is traceable quality control without inventing authority the inspector has not been delegated.`,[
['What makes an inspection hold point releasable?','Required evidence meets the stated criteria and authorized release occurs.','The crew attended a toolbox talk.','The contractor needs to move equipment.','The inspector has seen similar work elsewhere.','Hold points depend on criteria, evidence and delegated authority.'],
['What should distinguish direct observation from a contractor statement?','The report labels the source of the information.','Nothing; both are always equivalent.','Only the font size.','The statement should be rewritten as witnessed.','Evidence provenance matters when assessing what was actually verified.'],
['Backfill would hide a joint awaiting required coating inspection. Correct action is:','Maintain the hold and identify the exact joint until the required disposition.','Backfill and assume inspection will pass.','Delete the hold point.','Approve all neighboring joints instead.','Concealment would remove access needed to verify the requirement.']]],
['Right-of-way, excavation and environmental interfaces',`Construction inspection must connect the installed route with land, utility and environmental restrictions. Verify survey control, approved alignment, limits of disturbance, crossing permits, erosion controls and sensitive-area boundaries before ground disturbance. A proposed route drawing is not proof that underground utilities have been located or safely exposed. Utility information, locating marks and the excavation plan must be reconciled with actual field conditions.

Excavation hazards change with soil, depth, water, vibration, adjacent loads and weather. The employer's competent person evaluates the excavation and required protective system. Inspectors observe whether required controls and access are in place but should not invent a soil classification from a distant photograph. Stop and escalate conflicting utility indications, unexpected structures, water ingress or changing ground conditions through project authority.

Environmental measures must follow the site permits and plan. Separate topsoil where required, maintain sediment controls and protect water crossings. A route deviation around an obstruction can change cover, bending, property and permit assumptions; it requires controlled approval and as-built survey.

Case: the crew moves 3 m outside the approved corridor to avoid rock. The learner identifies alignment, permit, landowner and design implications, records station limits and requests the authorized change process. Practical assessment requires a marked route plan and a field walk with a qualified assessor. Critical failures include approving an unlocated utility crossing, entering an unprotected excavation or calling a proposed deviation an as-built record.`,[
['A proposed route drawing proves which fact?','Design intent, not verified underground utility position.','All buried utilities are absent.','Excavation protection is unnecessary.','The installed route matches the drawing.','Design drawings and field verification serve different purposes.'],
['A route shifts outside the approved corridor. What follows?','Review design, land and permit implications through change control.','Treat the shift as a survey correction only.','Backdate the original drawing.','Assume three metres is always negligible.','Even a small deviation can cross legal, environmental or engineering boundaries.'],
['Who evaluates excavation protection under the employer’s program?','The assigned competent person with required capability and authority.','Any person who has taken this quiz.','The delivery driver by default.','The photographer alone.','Excavation decisions require the designated competent person, not mere course attendance.']]],
['Pipe receipt, bending and weld traceability',`Material control starts before pipe enters the trench. Reconcile purchase specifications, markings, heat numbers, material certificates, dimensions and condition. Damaged bevels, dents, gouges or coating require the applicable evaluation; do not grind or repair a pressure-boundary defect without an approved method. Preserve identity when pieces are cut so installed segments remain traceable.

Cold bends change geometry and can introduce ovality, wrinkling or coating damage. Verify the approved bending procedure, equipment, location and dimensional acceptance basis. A bend that fits the trench is not automatically acceptable. Pipe grade, wall, seam position and bend geometry may matter under the actual specification.

Weld maps connect joint number, pipe identities, WPS, welder IDs, date and NDE. Before welding, verify fit-up, cleanliness, approved procedure revision and personnel range. During production, record required parameters and controls. After welding, retain repairs and reexamination in the same traceable chain rather than replacing a failed result with a clean final page.

Assessment: a 12 m pipe is cut into two pieces, but only one retains its heat mark; a weld map lists a welder not on the approved roster. The learner must reconcile both before acceptance. The assessor checks actual identity transfer, map consistency and a comparison against supplied fictional WPS limits. Changing a heat number from memory or treating a radiograph as proof of material grade is a critical failure.`,[
['When pipe is cut, what must the traceability process preserve?','Identity linking each installed piece to its material evidence.','Only the original total length.','Only the supplier logo.','Only the invoice date.','Material identity must survive cutting and installation.'],
['A bend fits the trench. Is that enough for acceptance?','No; dimensional and material/procedure requirements still apply.','Yes, fit proves all bend properties.','Yes, coating damage is irrelevant.','Yes, ovality cannot occur.','Fit alone does not assess ovality, wrinkles, damage or procedure compliance.'],
['A final NDE report follows a weld repair. What should the file retain?','Original findings, repair identity and reexamination results.','Only the final clean page.','Only the welder’s attendance sheet.','No repair history after acceptance.','Repair history is part of the installed joint’s traceable quality evidence.']]],
['Coating, lowering-in and backfill',`Pipeline coating is a barrier system whose performance depends on surface preparation, application, cure, continuity and damage control. Confirm the coating procedure and product requirements for surface condition, ambient conditions, mixing where applicable, thickness and cure. A visually uniform coating can contain holidays or inadequate adhesion. Holiday testing must use the correct method and voltage for the specified coating and thickness; arbitrary high voltage can damage the coating.

Before lowering-in, inspect coating condition, repairs, trench bedding and lifting arrangements. Controlled supports prevent excessive bending or concentrated damage. The lifting plan and equipment capacities belong to competent lifting personnel; the inspector verifies the specified checks and records deviations. Dragging the line across abrasive ground can invalidate previously satisfactory coating evidence.

Backfill can damage coating or create concentrated loads if unsuitable material or placement is used. Verify padding, cover, separation and warning/marker requirements against the actual design and permits. Survey installed position before concealment. Future maintenance needs actual location, depth and crossing information rather than the proposed route.

A practical exercise uses a training coated pipe with deliberately introduced safe defects and a supplied procedure. The learner documents surface condition, verifies instrument setup with the assessor, maps indications, records approved repairs and rechecks repaired locations. Acceptance requires traceable results and correct limits; a generic statement that the line was checked is insufficient. Actual energized holiday testing requires trained personnel and the approved equipment procedure.`,[
['Why is arbitrary higher holiday-test voltage inappropriate?','It can damage coating and may violate the specified method.','More voltage is always safer.','Voltage never affects coatings.','It replaces thickness measurement.','Test parameters must match the coating and procedure.'],
['Coating passed before the line was dragged over abrasive ground. What is required?','Evaluate and inspect for damage before concealment.','Rely solely on the earlier result.','Assume dragging improves adhesion.','Delete the earlier inspection.','A subsequent damage event can invalidate the condition represented by the earlier inspection.'],
['Which survey is needed for closeout?','The actual installed position and required depth/crossing data.','Only the original proposed route.','Only a satellite image without control.','Only the delivery address.','As-built records must describe the installed asset.']]],
['Pressure-test review and numerical checks',`The inspector reviews a pressure-test package against the approved project basis. Identify segment boundaries, elevations, material and component limitations, test medium, temperature, pressure limits, hold period, instrumentation, disposal and exclusion controls. Pressure testing is a controlled high-energy activity; this course does not authorize selecting test pressures or standing near a pressurized boundary.

Use static-head arithmetic to understand the plan. A water-filled test segment with 30 m elevation difference has about 294.3 kPa pressure difference between high and low points. If a supplied fictional high-point target is 5.0 MPa, the low point is approximately 5.294 MPa, ignoring other effects. Every component must be evaluated for its actual pressure; one gauge value cannot be applied uniformly over elevation.

Volume calculations help reconcile planned fill quantities. A simplified 1 km segment with 0.30 m internal diameter has volume pi*D²*L/4 = approximately 70.7 m³. Real fill volumes include fittings and boundaries, and trapped air must be controlled under the approved procedure. An unexpected volume discrepancy warrants review, not concealment.

Assessment requires independently checking the elevation correction and volume, reviewing gauge calibration and tracing the recorded hold period. The learner must identify temperature effects and missing boundary evidence without inventing a leak diagnosis. Pass only when the report distinguishes planned values, measured values and authorized interpretation.`,[
['Water across 30 m elevation produces approximately:','294.3 kPa difference','29.43 Pa difference','3 MPa difference','No pressure difference','rho*g*h = 1000*9.81*30 = 294300 Pa, or 294.3 kPa; pressure is greater at the lower elevation.'],
['A 1 km pipe with 0.30 m internal diameter has approximate internal volume:','70.7 m³','300 m³','7.07 m³','7068 m³','pi*(0.30²)*1000/4 is about 70.7 cubic metres.'],
['What must be distinguished in a test report?','Planned criteria, actual measurements and authorized interpretation.','Only the planned and invoiced quantities.','Only pass/fail color.','Only the inspector’s name.','A plan is not performance evidence, and raw readings require interpretation against criteria.']]],
['Restoration, turnover and practical inspection assessment',`Closeout verifies both the constructed asset and the obligations surrounding it. Reconcile as-built surveys, material and weld maps, NDE, coating repairs, test records, cathodic-protection interfaces where applicable, crossing records, valve identification and outstanding nonconformances. Restoration includes erosion controls, drainage, topsoil, land commitments and monitoring required by permits. A mechanically complete line may still have unresolved environmental obligations.

Create a punch list with location, requirement, finding, owner, due date and closure evidence. Distinguish a cosmetic item from a pressure-boundary, location or protective-system issue. The project authority decides commissioning readiness under its requirements; the inspector should not bury critical incomplete work in a general accepted-with-comments label.

Capstone: a completed segment has a passing pressure test, two unresolved coating repairs, one missing heat transfer and a route deviation absent from the survey. The passing test does not resolve any of those identity, corrosion-protection or location deficiencies. The learner prepares a bounded turnover recommendation and identifies each needed closure.

The practical rubric requires an assessor-observed review of a mock construction spread and dossier. Evaluate traceability, dimensional checks using supplied criteria, correct hold-point action, clear reporting and escalation. Each must pass; falsified witness status, concealed nonconformance or unsafe entry is a critical failure. API 1169 eligibility and examination remain separate, and actual project specifications/regulatory scope must be supplied for job acceptance.`,[
['Does a passing pressure test resolve missing material identity?','No; material traceability remains a separate requirement.','Yes, pressure proves the heat number.','Yes, if the segment is buried.','Yes, if the test lasted long enough.','Testing cannot establish material provenance.'],
['An environmental restoration obligation remains open. Turnover should:','Identify its owner, required closure and effect on release.','Delete it because welding is complete.','Mark it closed based on pressure testing.','Ignore it if no leak occurred.','Project and permit obligations require their own completion evidence.'],
['Which record constitutes an as-built deviation?','A verified record of the installed route approved through the project process.','An estimated line drawn from memory.','The unchanged design drawing.','A contractor’s verbal assurance alone.','As-built status requires evidence of actual installation, not intent or recollection.']]]
],[API+'api1169','https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.651'],['Six construction-inspection lessons with hold-point decisions, materials/weld maps, coating/backfill, head/volume calculations and turnover casework.'],['Actual project specifications, permit conditions, full US/Canadian API 1169 reference crosswalk and field inspector practical authorization are not supplied.']);

add('OG24',[
['Welding processes and inspection consequences',`Shielded metal arc welding uses a consumable flux-covered electrode; the coating contributes shielding and slag. Gas metal arc welding uses a continuously fed wire and external shielding gas. Flux-cored arc welding uses tubular wire, with shielding supplied by flux and sometimes external gas. Gas tungsten arc welding uses a nonconsumable tungsten electrode and separate filler when needed. Submerged arc welding operates under granular flux. These differences affect access, productivity, discontinuities and the variables an inspector must verify.

Shielding protects the molten weld pool from atmospheric contamination. Wind or unsuitable gas flow can compromise gas-shielded processes. Slag-producing processes require appropriate cleaning between passes; trapped slag is not eliminated by a smooth final cap. GTAW tungsten contamination and GMAW lack of fusion are different concerns requiring different evidence. Do not assign a process merely from bead appearance when records are available.

Current, voltage and travel speed influence energy input and bead shape, but procedure limits govern production. Increasing travel speed at unchanged electrical power reduces energy per unit length. A broad bead is not proof of complete fusion at the root or sidewall. Joint access and technique also affect the result.

Assessment: identify processes from equipment diagrams, explain the shielding mechanism and match likely discontinuities to inspection opportunities. The assessor supplies a WPS and asks which observable variables must be recorded. Pass requires correct process identification and a rationale; memorizing an acronym without recognizing its inspection consequences is insufficient.`,[
['Which process uses a nonconsumable tungsten electrode?','GTAW','SMAW','SAW','FCAW','GTAW uses tungsten to sustain the arc; filler is separately added when required.'],
['At unchanged current and voltage, faster travel generally does what to energy per unit length?','Decreases it.','Increases it.','Leaves it unchanged.','Makes shielding unnecessary.','The same electrical energy is distributed over more weld length per unit time.'],
['Why inspect cleaning between slag-producing passes?','Trapped slag can remain even if the final surface looks smooth.','Slag always evaporates.','The cap proves every buried pass is sound.','Cleaning establishes welder qualification.','Interpass cleanliness affects internal discontinuities that final appearance may conceal.']]],
['Metallurgy, heat input and discontinuity reasoning',`A fusion weld includes deposited weld metal, a heat-affected zone and unaffected base metal. Cooling history, composition and restraint influence hardness, toughness, distortion and residual stress. In susceptible steels, hydrogen, a hard microstructure and tensile stress can combine to produce delayed cracking. Controls may include consumable handling, approved preheat/interpass practice and qualified heat treatment; an inspector verifies the specified controls rather than inventing temperatures.

For an educational electrical-energy calculation, heat input before efficiency correction is voltage × current ×60 divided by travel speed in mm/min, producing joules/mm. At 24 V, 200 A and 240 mm/min, the value is 1200 J/mm or 1.2 kJ/mm. A supplied efficiency factor of 0.8 would give 0.96 kJ/mm in that model. Actual code definitions and procedure limits must be checked before using an efficiency factor.

Distinguish porosity, slag inclusion, undercut, overlap, lack of fusion, incomplete penetration and cracking. A discontinuity becomes a defect when it fails applicable acceptance criteria. Shape, orientation, location and service matter; the same length limit cannot be assumed for every indication. Cracks require particularly careful evaluation under the governing standard.

Practical desk assessment uses section sketches and photographs with known answers. Learners identify plausible discontinuities, state what the image cannot prove and choose further examination. The assessor checks the heat-input arithmetic and rejects acceptance based on appearance alone or an invented universal discontinuity limit.`,[
['24 V, 200 A and 240 mm/min gives electrical energy per length of:','1.2 kJ/mm','12 kJ/mm','0.12 kJ/mm','48 kJ/mm','24*200*60/240 = 1200 J/mm = 1.2 kJ/mm.'],
['Which combination supports hydrogen-assisted cracking in susceptible steel?','Hydrogen, susceptible microstructure and tensile stress.','Only a large bead.','Only high ambient humidity regardless of material.','Only an unpainted surface.','Hydrogen cracking depends on interacting metallurgical and stress conditions.'],
['When is a discontinuity a defect?','When it is unacceptable under the applicable criteria.','Whenever it can be photographed.','Only when it leaks.','Never if the welder is qualified.','Acceptance is a criteria-based disposition, not a synonym for any indication.']]],
['Drawings, welding symbols and dimensional interpretation',`A welding symbol communicates the joint requirement through a reference line, arrow and applicable symbols, dimensions and notes. Use the drawing's adopted symbol standard; arrow-side conventions and supplementary information must be interpreted under that standard. Do not infer a weld on both sides from a single-side requirement or omit a tail note identifying a process or specification.

Joint geometry includes groove angle, root opening, root face, alignment and backing where specified. Fillet weld leg size and effective throat are different dimensions. For an ideal equal-leg fillet with a 90-degree joint, the geometric throat is approximately 0.707 times the leg. A 6 mm leg therefore gives about 4.24 mm geometric throat. Actual effective throat rules can differ with penetration and code provisions; this geometry exercise is not a universal design rule.

Intermittent weld length and pitch describe different things. In a fictional drawing requiring 50 mm weld segments on 150 mm center-to-center pitch, the clear nominal gap is 100 mm along a simple straight arrangement. A note requiring continuous sealing would conflict with interpreting the joint as intermittently sealed; resolve drawing conflicts before fabrication.

Assessment uses a controlled drawing with three welds and a dimensional specimen. The learner translates each symbol into a plain-language requirement and marks the measurement locations. The assessor verifies side, length, size and notes. Critical failures include fabricating a missing dimension or measuring reinforcement as if it were the specified fillet leg.`,[
['An ideal equal-leg 6 mm fillet has approximate geometric throat:','4.24 mm','6 mm','8.49 mm','3 mm','0.707*6 = 4.242 mm for the stated ideal geometry.'],
['50 mm welds on 150 mm center-to-center pitch leave a nominal straight-line gap of:','100 mm','150 mm','200 mm','50 mm','Pitch minus weld length gives the clear gap in the stated arrangement.'],
['A symbol conflicts with a sealing note. What should the inspector do?','Obtain controlled clarification before accepting fabrication.','Choose the easier interpretation.','Erase the note.','Assume every weld is continuous.','Conflicting design requirements require resolution by the authorized design process.']]],
['WPS, PQR and performance qualification',`The WPS states how production welding is to be performed. A PQR records actual qualification variables and test outcomes supporting the procedure where required. A welder performance qualification records an individual's demonstrated range. Prequalified procedures exist under some standards and conditions, but prequalification is not a universal exemption from controlled instructions or personnel qualification.

Build a comparison matrix: production process, material grouping, thickness, diameter where relevant, position, joint/backing, filler, shielding, electrical characteristics, preheat/interpass and heat treatment. Compare each to the WPS and governing qualification rules. Essential, supplementary essential and nonessential variable categories are code-specific; a familiar term does not justify applying one code's ranges to another.

Case: production requires GTAW root plus SMAW fill. The welder record covers only SMAW. The WPS may be valid for both processes, but this person's GTAW scope is not established. A second case has a valid welder record but an unapproved shielding-gas substitution; personnel qualification does not approve the procedure change.

Assessment requires two complete matrices and supporting references from supplied licensed documents. The assessor checks that the learner separates procedure and person, identifies every mismatch and avoids inventing qualified thickness ranges. A passing record names the actual document revision, qualification basis and unresolved items. Production release remains with the assigned authority.`,[
['A WPS covers GTAW and SMAW but a welder record covers only SMAW. What remains missing?','The person’s applicable GTAW qualification.','The existence of any welding procedure.','The SMAW process definition.','Only a photograph.','Procedure scope and individual performance scope are independent.'],
['Can a valid welder record approve an unreviewed gas substitution?','No; procedure-variable requirements still govern.','Yes, qualification covers every gas.','Yes, if gas cylinders fit.','Yes, if the weld looks brighter.','Personnel skill does not authorize a changed procedure variable.'],
['Where do essential-variable categories and qualified ranges come from?','The applicable governing qualification standard and records.','The inspector’s preferred rule of thumb.','Only the job title.','The largest range seen on any previous project.','Ranges and variable categories are specific to the adopted framework.']]],
['Visual examination and measurement reliability',`Visual inspection occurs before, during and after welding. Before welding, check identification, fit-up, cleanliness, bevels and approved procedure/personnel scope. During welding, observe required parameters, preheat/interpass controls and cleaning. After welding, examine dimensions, profile and accessible discontinuities under suitable lighting and access. Final inspection cannot recover every hidden fit-up condition.

Select the correct gauge for the feature. A fillet gauge, bridge cam gauge, straightedge and ruler do not measure identical things. Verify instrument condition and zero/reference checks as applicable. Record units and measurement location. Surface roughness, access angle and inconsistent contact can create reading errors. Do not round a marginal value until the actual acceptance method permits it.

In a supplied fictional criterion, undercut must not exceed 0.5 mm. A measurement of 0.6 mm is nonconforming under that criterion; the inspector cannot round it to zero. If measurement uncertainty is significant near the limit, apply the specified decision rule or obtain a more suitable measurement. The fictional limit is not a general AWS acceptance value.

Practical assessment uses calibrated training replicas with known discontinuities and dimensional values. Require the learner to select the gauge, demonstrate contact, record repeated readings and apply supplied criteria. The assessor scores detection, measurement and disposition separately. Missing a planted crack-like indication or falsifying a reading is a critical failure; an uncertain measurement should be reported and resolved rather than hidden.`,[
['Why inspect fit-up before welding?','Some conditions become inaccessible after welding.','It replaces all final examination.','It proves the weld has no internal flaws.','It eliminates procedure requirements.','The opportunity to verify root geometry or cleanliness may disappear after deposition.'],
['Under a supplied 0.5 mm maximum, a reliable 0.6 mm reading is:','Nonconforming to that fictional criterion.','Automatically rounded to acceptable.','Always acceptable under all codes.','Meaningless because it is less than one millimetre.','The measured value exceeds the stated criterion; actual code limits must be supplied for real work.'],
['Near-limit measurement uncertainty should be:','Addressed using the specified decision rule or better measurement.','Deleted from the report.','Used to choose the most favorable answer automatically.','Ignored because the gauge has a serial number.','Calibration alone does not remove setup, resolution and repeatability effects.']]],
['Code application and inspector practical capstone',`Inspection conclusions need the applicable construction/service code, edition, drawing revision and project criteria. A method standard may explain how to examine without specifying acceptance for the component. Find the correct acceptance section and its notes, joint type, loading category and examination extent. Do not transfer a pressure-piping limit to a structural weld because both are steel.

Capstone includes a drawing, WPS, PQR, welder records, heat certificates, parameter log, visual measurements and NDE report. The specimen has correct fillet dimensions but an undocumented procedure change and incomplete required NDE. Dimensional conformity alone does not close those gaps. The learner writes a report separating conforming measurements, nonconformances and unverified requirements.

Assessor rubric: identify all planted document conflicts; measure three features within the training specimen's established tolerance; correctly classify supplied discontinuities; cite the supplied acceptance basis; issue a bounded disposition. All domains must pass. Unsafe handling, invented readings or accepting a known unresolved critical condition requires remediation and a new independent attempt. Retain specimen identity and assessor qualifications with the evidence.

AWS CWI has its own eligibility, vision and examination requirements, including fundamentals, practical and code application. This original VNDRLY course develops specific knowledge and practical-review skills but does not claim complete CWI exam coverage, access to proprietary replicas or an AWS credential. Selected-code study with current authorized references remains necessary.`,[
['Does a method standard always provide component acceptance criteria?','No; acceptance may come from a separate construction/project requirement.','Yes, every method standard accepts every weld.','Yes, the instrument manual always overrides the code.','No acceptance criteria are needed.','Examination technique and component acceptance are distinct functions.'],
['A weld has correct dimensions but incomplete required NDE. Disposition is:','Dimensional conformity established; overall acceptance remains incomplete.','Fully accepted.','Automatically rejected for every possible flaw.','Equivalent to CWI certification.','A passing dimensional check does not substitute for other required evidence.'],
['What evidence makes the practical assessment reproducible?','Specimen identity, known criteria, recorded measurements and assessor record.','Only a completion badge.','Only an attendance list.','Only the learner’s confidence rating.','Traceable specimens and criteria permit an independent review of actual performance.']]]
],[AWS+'certified-welding-inspector/','https://www.aws.org/certification-and-education/education/in-person-training/certified-welding-inspector-part-b/'],['Process physics, metallurgy/heat-input math, symbol geometry, qualification matrices, gauge exercises and code-based capstone.'],['Full current CWI BOK, selected-code clauses, symbol-standard reproduction, AWS replica exercises and independently delivered practical examination are not supplied.']);

add('OG25',[
['NDT qualification, method selection and common controls',`Nondestructive testing asks a defined question about a material or component without intentionally destroying its serviceability. Choose a method from the expected discontinuity, material, geometry, access and required detection capability. Detection, characterization and acceptance are different stages. A negative result supports only the method's demonstrated coverage and sensitivity under the actual conditions.

Method qualification is specific. UT competence does not establish RT, MT or PT competence. ASNT NDT Level II general and specific examinations are distinct from employer practical and job-specific responsibilities. Employer-based written practices and third-party schemes have different requirements; record the actual scheme, method, sector, training, experience, vision and practical evidence rather than using one generic NDT badge.

Before an examination, verify approved procedure, personnel scope, equipment, reference standards, surface/access conditions, calibration or standardization and reporting criteria. During work, monitor conditions that could invalidate the setup. After work, perform required checks and preserve raw data and coverage. A failed post-check requires assessment of affected results, not just recalibrating and signing the report.

Case: an instrument checks correctly before a shift but drifts beyond the procedure limit afterward. The learner identifies the affected time window, preserves results and seeks the required reexamination/disposition. Assessor criteria require clear method limits and an evidence-based affected-scope decision. This shared foundation is followed by separate method lessons; it is not a claim of completed training hours for every NDT method.`,[
['Does UT qualification establish MT qualification?','No; qualifications are method-specific.','Yes, both are nondestructive.','Yes, if the technician has ten years of service.','Yes, if the same report form is used.','Methods have different physics, procedures and demonstrated skills.'],
['A post-examination check fails. What should happen?','Assess affected results and reexamination under the procedure.','Recalibrate and silently retain all results as valid.','Delete the failed check.','Assume the first check guarantees the entire shift.','Drift may invalidate data collected since the last acceptable check.'],
['A negative result establishes:','Only the bounded result for actual method, coverage and sensitivity.','Absence of every flaw in every orientation.','Unlimited fitness for service.','All required personnel credentials.','Method limitations prevent an unrestricted no-defects conclusion.']]],
['Ultrasonic testing: travel time, geometry and calibration',`UT transmits sound into a material and interprets returned or transmitted energy. In pulse-echo straight-beam thickness measurement, sound travels to the reflector and back, so thickness equals velocity times round-trip time divided by two. For supplied longitudinal velocity 5900 m/s and time 4 microseconds, thickness is 5900×0.000004/2 = 0.0118 m, or 11.8 mm. Incorrect material velocity creates a systematic thickness error.

Angle-beam inspection uses refraction and beam geometry to interrogate weld regions. With a supplied refracted angle of 60 degrees from the surface normal and sound path 40 mm, depth is 40 cos60° = 20 mm and surface distance is 40 sin60° = 34.6 mm before considering skips and actual geometry. These are geometry exercises, not a production scan plan.

Standardization must address time base/range, probe index and angle where applicable, sensitivity/reference response, transfer effects and equipment checks under the procedure. Coupling, roughness, temperature, grain structure and geometry affect response. A strong echo is not automatically a crack; a weak echo is not automatically harmless. DAC/TCG and sizing approaches require the specific qualified technique.

Practical assessment uses safe reference blocks and a specimen with known reflectors. A qualified UT assessor observes setup, systematic coverage, position calculation, interpretation and report limitations. Require repeatable results under the supplied procedure. Missing an entire scan region, using the wrong velocity or inventing a reflector size is a critical failure.`,[
['5900 m/s velocity and 4 microseconds round-trip time gives thickness:','11.8 mm','23.6 mm','1.18 mm','236 mm','Pulse-echo distance is divided by two because the sound travels out and back.'],
['At 60° from normal and 40 mm sound path, depth is:','20 mm','34.6 mm','40 mm','80 mm','Depth is the normal component: 40*cos60° = 20 mm.'],
['What is a consequence of using the wrong acoustic velocity?','Systematic distance/thickness error.','Only a change in report color.','Guaranteed detection of more cracks.','No effect if the probe is clean.','Time-to-distance conversion directly depends on velocity.']]],
['Radiographic testing: image geometry and radiation boundaries',`RT forms an image from differences in radiation transmission. Material thickness, density, beam energy and geometry affect image contrast. Volumetric discontinuities such as porosity can produce visible density changes; planar flaws may be difficult to detect when their orientation gives little effective thickness change along the beam. RT is therefore not an orientation-independent guarantee of weld soundness.

Geometric unsharpness increases with source size and object-to-detector distance and decreases with source-to-object distance. In a supplied simplified model Ug = F×b/a, source size F = 2 mm, object-to-detector distance b = 50 mm and source-to-object distance a = 500 mm give Ug = 0.2 mm. Halving b halves this modeled unsharpness. Actual technique acceptance includes more than this calculation.

Image-quality indicators, identification markers, coverage, density or digital response, sensitivity and processing/display controls establish whether an image is interpretable under the procedure. An IQI demonstrates specified image quality, not that every possible flaw would be found. An image with ambiguous joint identity cannot be applied to a convenient weld number.

Radiation work requires licensed/authorized personnel, controlled areas, surveys and the applicable radiation-protection program. This course provides image-review reasoning only and no source-handling or exposure setup authorization. Practical assessment uses archived or simulated images with known indications. The assessor checks identity, image quality, interpretation and application of supplied acceptance criteria before any accept/reject conclusion.`,[
['With F=2 mm, b=50 mm and a=500 mm, Ug equals:','0.2 mm','2 mm','20 mm','0.02 mm','Using the supplied geometry model, 2*50/500 = 0.2 mm. Increasing object-to-detector distance would increase this unsharpness.'],
['Why can a planar flaw be difficult to detect by RT?','Its orientation may produce little transmission-thickness contrast.','RT never detects any discontinuities.','Planar flaws are always acceptable.','An IQI eliminates orientation effects.','Radiographic detectability depends on geometry and contrast along the beam.'],
['What does a satisfactory IQI establish?','The specified image-quality evidence, not universal flaw detection.','Every crack has been detected.','The welder is qualified.','The radiation area is safe without surveys.','IQIs assess image quality under the technique; they do not replace all examination or radiation controls.']]],
['Magnetic particle testing: fields and interpretation',`MT detects magnetic flux leakage associated with discontinuities in ferromagnetic material. A discontinuity oriented approximately perpendicular to the magnetic field generally gives a stronger response than one parallel to it. Examination in more than one appropriate field direction is therefore important when flaw orientation is not known. Austenitic stainless steel is generally unsuitable for conventional MT because it is not ordinarily ferromagnetic in the needed sense.

Magnetization techniques differ in field direction and near-surface or deeper response. Current waveform, equipment arrangement, surface condition and particle system affect sensitivity. Use the approved procedure for magnetization, field adequacy and particle application; do not select current from a generic internet rule. Yoke performance checks, field indicators, illumination and bath/process controls are examples of required system checks depending on the technique.

Relevant indications must be distinguished from geometry, permeability changes and other nonrelevant responses. A threaded edge or abrupt section change can attract particles without a crack. Cleaning and repeat examination may support interpretation, but indications must not be wiped away and ignored simply because they are inconvenient. Demagnetization and post-cleaning may be required for subsequent service.

Practical assessment uses a safe training specimen with known surface discontinuities and a supplied procedure. A qualified MT assessor checks field orientation, system checks, coverage, indication location and bounded interpretation. Pass requires detection in the appropriate orientation and correct records; using MT on an unsuitable material or omitting required orthogonal coverage is a critical failure.`,[
['A flaw parallel to the magnetic field may be:','Less detectable than one perpendicular to it.','Always more detectable.','Automatically acceptable.','Unrelated to field direction.','Flux leakage is generally stronger when a discontinuity interrupts the field.'],
['Which material is generally unsuitable for conventional MT?','Austenitic stainless steel lacking suitable ferromagnetism.','Ferromagnetic carbon steel.','Ferromagnetic low-alloy steel.','A known ferromagnetic training specimen.','MT requires suitable ferromagnetic behavior.'],
['Particles gather at a geometric transition. What is required?','Interpret whether the response is relevant under the procedure.','Automatically call every accumulation a crack.','Always erase and accept it.','Replace the material certificate.','Geometry and permeability changes can create nonrelevant responses that require disciplined interpretation.']]],
['Penetrant and visual testing: surface access and sequence',`PT reveals discontinuities open to a suitable nonporous surface. The sequence includes preparation, penetrant application, specified dwell, controlled excess removal, developer application, development and examination under required lighting. Each stage affects sensitivity. Excessive cleaning can remove penetrant from a discontinuity; inadequate cleaning can leave background that obscures indications. Dwell and development times come from the approved system/procedure, not a universal number.

Surface coatings, smeared metal, dirt and porous materials can defeat or confuse PT. A negative PT result does not exclude subsurface flaws. Linear versus rounded indications require interpretation and the applicable acceptance criteria. Developer draws penetrant back from surface openings, making the indication visible; the visible indication dimensions are not automatically the physical flaw dimensions.

VT depends on access, illumination, viewing angle, resolution and the examiner's visual capability. Direct and remote methods have different limitations. A borescope image can document an accessible surface but needs location/orientation and an appropriate scale for measurement. A clear image is not a volumetric examination.

Practical assessment uses nonhazardous training conditions and manufacturer-approved materials with a qualified assessor. The learner demonstrates surface suitability, correct sequence, lighting checks, timing records and reporting on known specimens. Critical failures include applying PT through paint, skipping required removal controls or converting a surface-only result into proof of internal soundness. Chemical handling and ventilation follow the actual product SDS and work controls.`,[
['PT detects which class of discontinuity?','Those open to a suitable examined surface.','Every buried discontinuity.','Only changes in magnetic permeability.','Only thickness loss through sound timing.','Penetrant must enter an opening connected to the surface.'],
['Excessive removal of penetrant can cause:','Loss of sensitivity by removing penetrant from openings.','Guaranteed stronger indications.','No effect on results.','Automatic demagnetization.','Over-cleaning can remove the material needed to form an indication.'],
['A clear borescope image proves:','The observed surface condition within its actual access and resolution.','Absence of every internal flaw.','Full wall thickness everywhere.','All NDT methods are unnecessary.','VT evidence is bounded by view, resolution and surface access.']]],
['Method-specific practical plan and integrated NDT report',`A Level II preparation program must specify method and sector. The six lessons here supply a cross-method technical foundation and distinct UT, RT, MT, PT and VT exercises; they do not combine into a universal multi-method certification. Actual training hours, experience, examinations and employer authorization follow the selected scheme and written practice. ASNT's published method outlines have transition dates, including MT and UT changes across 2026–2027, so select the outline that applies to the examination date.

An NDT report identifies component, material, procedure revision, personnel qualification, equipment/reference checks, technique parameters, examination extent, indications, evaluation criteria and limitations. Preserve raw images or scans where required. Distinguish incomplete coverage from completed coverage with no relevant indications. A repair requires traceable reexamination under its defined requirements.

Capstone: a weld has satisfactory PT, an RT image with incomplete coverage and a UT result from an unverified velocity setting. PT does not fill the volumetric gap, and an attractive scan cannot validate the wrong setup. The correct result is separate bounded findings and a reexamination/disposition plan.

The assessor selects one method for a full practical demonstration using known specimens and a controlled procedure. Score setup, calibration/standardization, systematic coverage, detection/interpretation, criteria application and reporting separately; all must pass. Require a new independent attempt after critical errors. Record actual performance evidence and method scope rather than issuing a generic Level II claim from a quiz score.`,[
['Can satisfactory PT fill missing RT volumetric coverage?','No; the methods address different detection questions.','Yes, all NDT results are interchangeable.','Yes, if PT found no indications.','Yes, if both reports use the same date.','Surface-opening evidence cannot supply missing volumetric examination.'],
['Which ASNT outline should guide exam preparation during a published transition?','The method outline applicable to the scheduled examination date.','Always the future outline.','Always the oldest outline.','Any outline from another method.','Published transition dates determine the applicable examination topic set.'],
['A practical record should state:','The actual method, specimen, procedure, observed results and assessor.','Only a generic Level II title.','Only online quiz completion.','Only years employed.','Method-specific performance evidence is necessary to establish what was demonstrated.']]]
],[ASNT,'https://certification.asnt.org/certification/asnt-ndt-level-ii'],['Six lessons, including separate UT, RT, MT, PT/VT teaching and numerical geometry/time-of-flight cases; method-specific practical rubric.'],['Not a complete method-specific Level II training-hours program or employer certification. ET, leak, acoustic emission and other methods are not taught. Full method/sector outlines, qualified procedures, specimens, experience and actual practical examinations must be provided for selected scope.']);

add('OG44',[
['Welder work package and qualification boundaries',`Welder qualification demonstrates performance within a defined range under a governing standard. It does not qualify every process, position, thickness, diameter, material or backing condition. Start by identifying the production joint, applicable code, approved WPS and the welder's actual performance record. An AWS CWI credential concerns inspection and does not itself qualify someone to make a production weld.

Read the WPS as a set of instructions: process sequence, materials, joint geometry, filler, shielding, electrical variables, preheat/interpass controls, position and any heat-treatment requirements. Compare the production assignment to both the procedure and personnel scope. Where a variable is unfamiliar, resolve it before striking an arc. Qualification ranges come from the adopted code, not the range of settings available on the machine.

Case: a worker passed a plate SMAW test but is assigned a GTAW pipe root. The previous test is evidence of a particular demonstrated scope, not automatic coverage of the new assignment. A separate valid performance basis is needed. Conversely, a qualified GTAW welder still needs an approved WPS for the actual joint.

Assessment requires the learner to build a production-to-WPS-to-personnel matrix using supplied records. The assessor checks process, position, thickness/diameter and backing comparisons under the actual standard. Missing scope is a hold, not an invitation to guess. Retain the comparison and qualification record identity with the training result.`,[
['Does CWI certification itself qualify a person to make a production weld?','No; welding performance qualification is separate.','Yes, for every process.','Yes, for all positions.','Yes, if the person inspects their own work.','Inspection certification and welder performance qualification have different purposes.'],
['A SMAW plate qualification automatically covers a GTAW pipe root:','False; process and applicable range must be established.','True for every code.','True if the pipe is small.','True if the same employer signs.','Process and product/range changes require review under the governing rules.'],
['Which comparison is needed before production?','Actual joint versus WPS and individual qualification scope.','Only machine maximum amperage.','Only years employed.','Only the electrode box color.','Both approved instructions and demonstrated personnel range must match the assignment.']]],
['Joint preparation, fit-up and consumables',`Joint preparation controls access to the root and sidewalls. Check bevel angle, root face, opening, alignment and backing against the WPS and drawing. Excessive mismatch can create stress concentration or make fusion difficult; an undersized opening can obstruct root access. Do not enlarge a gap or alter a bevel simply because a preferred technique works better on another job.

Remove contaminants using the approved preparation method. Oil, moisture, oxide and unsuitable coatings can affect porosity, hydrogen and fusion. Cleaning methods must not introduce incompatible contamination. Stainless and other alloy work may need dedicated tools and controlled cleanliness. Identify and segregate base materials and filler; similar-looking wire can have different chemistry.

Consumable condition matters. Follow the approved storage, exposure and reconditioning requirements for the actual electrode or wire. A low-hydrogen designation does not guarantee low hydrogen after uncontrolled moisture exposure. Gas identity, connections and flow setup follow the WPS and equipment instructions. More shielding-gas flow is not always better; turbulence can entrain air.

Practical assessment uses a cold training joint before welding. The learner measures fit-up, verifies material/filler identity and identifies a deliberately contaminated area or mismatched consumable. The assessor records actual measurements against supplied tolerances. Critical errors include concealing an out-of-tolerance root opening, using unidentified filler or treating surface appearance as proof of correct alloy.`,[
['Why does root opening matter?','It affects access and the ability to achieve the specified joint.','It changes only appearance after painting.','It replaces welding parameters.','Every opening is interchangeable.','Joint geometry controls access and deposited-weld configuration.'],
['A low-hydrogen electrode has been exposed outside its allowed storage conditions. What follows?','Disposition under the actual consumable/WPS requirements.','Use it because the label guarantees dryness forever.','Increase current without review.','Erase the exposure record.','Condition and handling affect hydrogen control despite the original designation.'],
['Similar-looking filler wire has no identity. Correct action is:','Hold it until traceable suitability is established.','Use it for the root only.','Use it if diameter matches.','Assume all steel fillers are identical.','Diameter and appearance do not establish filler chemistry or classification.']]],
['Arc control, energy and pass sequence',`The welder controls arc placement, travel, filler deposition and cleaning within the approved procedure. Too little fusion energy or poor access can leave unfused sidewalls; excessive heat can increase distortion, burn-through or unwanted metallurgical effects. A stable arc and attractive cap are useful observations but do not independently establish internal quality.

Energy per length helps explain parameter interactions. With a supplied 22 V, 180 A and travel speed 220 mm/min, electrical energy per length is 22×180×60/220 = 1080 J/mm, or 1.08 kJ/mm before any efficiency factor. At 330 mm/min with unchanged electrical settings, it is 0.72 kJ/mm. This is an educational calculation; actual allowed ranges and heat-input definitions come from the WPS/code.

Pass sequence and restraint influence distortion and residual stress. Tack welds incorporated into the final joint must meet the applicable requirements. Clean and inspect between passes, remove unacceptable conditions through an approved method and keep interpass temperature within the WPS. Do not bury a known crack or slag pocket under another pass.

During a supervised training coupon, the assessor observes parameter selection, travel control, cleaning, start/stop treatment and adherence to temperature controls. Record actual values rather than copying WPS limits as if they were measurements. Unsafe electrical setup, departure from the procedure or deliberate concealment of a discontinuity is a critical failure.`,[
['22 V, 180 A and 220 mm/min gives electrical energy per length:','1.08 kJ/mm','10.8 kJ/mm','0.108 kJ/mm','3.96 kJ/mm','22*180*60/220 = 1080 J/mm.'],
['Increasing speed to 330 mm/min at the same electrical settings gives:','0.72 kJ/mm','1.62 kJ/mm','1.08 kJ/mm','7.2 kJ/mm','Energy per length decreases in inverse proportion to travel speed.'],
['A known slag pocket is visible between passes. What is correct?','Resolve it by the approved method before covering it.','Bury it with a wide cap.','Treat it as harmless because it is internal.','Erase the observation.','Subsequent deposition does not reliably remove trapped discontinuities.']]],
['Discontinuities, feedback and controlled repair',`Learn to connect visible results with likely process causes without assuming a single cause from appearance. Porosity can relate to shielding or contamination; slag inclusions can relate to cleaning or bead placement; lack of fusion can involve access, energy or technique; undercut can involve arc placement and travel; cracks require metallurgical and stress evaluation. Diagnosis informs correction, but acceptance follows the governing criteria.

The welder should inspect accessible work at each stage and report suspected unacceptable conditions. An inspector or authorized technical role determines required examination and disposition. Grinding until a mark disappears can remove too much base metal or leave the true discontinuity; repairs need controlled excavation, confirmation, rewelding and reexamination where required.

Case: a training coupon has undercut and a linear surface indication near a stop/start. The learner must not classify both as cosmetic. Record location and dimensions, pause further work and seek the prescribed evaluation. A smooth repair cap is not proof that the original indication was removed or that the repair meets requirements.

Practical feedback should be specific: identify the observed problem, the variable or technique to review within the WPS, and the evidence required on the next coupon. The assessor distinguishes coaching practice from an independent qualification test. A learner may practice repeatedly, but only the actual controlled test and acceptance establish the recorded qualification scope.`,[
['Does a smooth repair cap prove complete removal of the original flaw?','No; removal and reexamination evidence are needed as required.','Yes, appearance proves internal soundness.','Yes, if the cap is wider.','Yes, if the same welder repaired it.','Surface finish cannot establish what happened beneath it.'],
['A linear surface indication at a stop/start should be:','Recorded and evaluated under the prescribed criteria.','Automatically called cosmetic.','Covered with paint.','Ignored if no leak is visible.','Linear indications may represent significant discontinuities and require evaluation.'],
['Coached practice coupons and an independent qualification test are:','Different evidence stages that must remain distinguishable.','Always the same event.','Interchangeable if attendance is recorded.','Unnecessary when the learner is confident.','Qualification requires its controlled conditions and acceptance, not just practice participation.']]],
['Performance test, destructive testing and evidence',`A performance test uses the governing standard's defined coupon, process, position and acceptance route. The test supervisor controls identity and conditions, and records actual variables. Visual examination commonly precedes further testing. Bend tests evaluate soundness and ductility of the tested region under their defined preparation and acceptance rules; radiography may be permitted for some scopes but is not universally interchangeable with every destructive test.

The coupon and removed specimens need traceability. Mark location and orientation before cutting, maintain specimen identity during preparation and record results individually. A failed specimen cannot be replaced by an unrelated successful specimen. Test-piece preparation errors must be documented and dispositioned under the standard, not concealed as a welder failure or silently retested.

The final performance record describes the actual test and qualified range derived from the applicable rules. It should not simply say certified welder. Include process, relevant variables, test date, examiner, results and scope. Employer acceptance or an AWS Certified Welder pathway may add specific administration requirements.

Assessment uses a mock test pack with coupon photographs, parameter log and specimen results. The learner reconstructs traceability and identifies a swapped specimen ID. The assessor requires accurate distinction between test variables and derived qualification range. Actual qualification must use authorized facilities/personnel and accepted test results; this online pack cannot supply a passed physical coupon.`,[
['What must survive coupon cutting?','Specimen identity, location and orientation traceability.','Only the total coupon weight.','Only the welder’s nickname.','Only a final pass stamp.','Test results must remain linked to the actual tested weld and specimen.'],
['Can an unrelated successful bend specimen replace a failed one?','No; substitution destroys test validity.','Yes, if the material looks similar.','Yes, if the same process was used.','Yes, if the report has not been signed.','Qualification depends on the controlled test, not selected favorable specimens.'],
['A performance record should distinguish:','Actual tested variables from the qualified range derived under the code.','Only pass from fail with no scope.','Only attendance from absence.','Only electrode brands.','The test conditions and the authorized range are related but not identical.']]],
['Continuity, safe work and final practical rubric',`Qualification maintenance depends on the governing standard and employer program. Track actual use of the process and any required continuity evidence; do not invent a universal interval for all codes. Loss of continuity, reason to question ability or a changed assignment can require review or requalification. A training refresher does not automatically restore a lapsed performance qualification.

Welding safety remains integral: electrical condition, fume control, fire prevention, eye/skin protection, compressed gases and confined-space controls must be appropriate to the actual work. Coatings and alloys can change fume hazards. A hot-work permit does not establish ventilation adequacy or authorize welding on an unidentified process boundary. Stop when the work package or safe conditions are not established.

Final supervised assessment uses a selected process and WPS on a training coupon. The assessor evaluates work-pack interpretation, fit-up, consumable handling, setup, welding technique, interpass controls, self-inspection and traceable handover. All critical criteria must pass, and the coupon must undergo the specified acceptance examinations. Record actual parameters, specimen identity, results and assessor authority.

The VNDRLY knowledge record covers these lessons and exercises. A code-specific performance credential is recorded only after real testing and accepted results under that code. Preserve failed attempts and remediation separately from the final test; doing so supports skill development without misrepresenting practice as qualification.`,[
['Can an online refresher automatically restore expired welder continuity?','No; the applicable code/employer requirements govern restoration.','Yes, for every code.','Yes, if the quiz score is perfect.','Yes, if a new badge is printed.','Knowledge refresh does not replace required performance or continuity evidence.'],
['Does a hot-work permit prove fume control is adequate?','No; exposure and ventilation controls require their own basis.','Yes, every permit covers all chemicals.','Yes, if work is indoors.','Yes, if the welder wears gloves.','Fire authorization does not establish exposure-control adequacy.'],
['When may code-specific performance qualification be recorded?','After the actual controlled test and accepted results establish the scope.','After reading these lessons alone.','After watching another welder.','After purchasing a welding machine.','Qualification is based on demonstrated and accepted performance within defined conditions.']]]
],[AWS+'certified-welder-program/'],['Six process/fit-up/energy/discontinuity/test/continuity lessons with a defined supervised coupon rubric and 18 checks.'],['Actual selected WPS/code limits, qualified instructor delivery, physical coupons, test results and authorized performance certification remain required.']);

add('OG45',[
['Corrosion cells and protective-coating systems',`A corrosion cell includes anodic and cathodic reactions, an ionic path through an electrolyte and an electronic path through metal. Coatings can interrupt environmental contact, provide inhibitive effects or offer sacrificial protection depending on the system. A barrier coating is not invulnerable: defects, permeation, adhesion failure and underfilm corrosion can undermine it.

Select a system for substrate, service temperature, immersion or atmospheric exposure, chemicals, ultraviolet exposure and mechanical damage. Primer, intermediate and finish coats have distinct functions and compatibility requirements. A coating suitable for atmospheric structural steel may be unsuitable as a tank lining. Product data sheets describe application and cure requirements; safety data sheets describe hazards and controls. Neither replaces the project specification.

Inspection follows the process: substrate condition, preparation, environment, mixing, application, cure and final testing. A thick final film cannot compensate for salt contamination or poor adhesion beneath it. Repairing a localized defect requires compatible preparation and recoating, not just hiding the area with a topcoat.

Exercise: compare a coastal structural-steel coating with an immersion lining. Identify environmental mechanisms, preparation needs, cure implications and inspection hold points. The assessor checks the rationale and rejects selection based only on color or brand familiarity. This technical coating course fills a specific gap: baseline G73 teaches hazardous-material survey limits, not coating-system inspection.`,[
['Why can a thick film still fail?','Contamination, adhesion failure or incompatibility can remain beneath it.','Thickness guarantees all preparation was correct.','Corrosion cells need no electrolyte.','Color determines corrosion resistance alone.','Barrier thickness is only one part of system performance.'],
['Which document primarily gives application and cure requirements?','The actual product data sheet, used with the specification.','Only the invoice.','Only the SDS hazard pictograms.','Only the inspector badge.','PDS application instructions and project requirements establish the working criteria.'],
['An atmospheric coating is proposed for tank immersion. What is needed?','Service-specific suitability and system approval.','Only matching color.','Only a thicker coat.','No review because both substrates are steel.','Immersion imposes different chemical and permeation demands.']]],
['Surface preparation, profile and soluble contamination',`Surface preparation removes contaminants and creates the condition needed for adhesion. Oil and grease must be addressed before abrasive cleaning rather than driven into the surface. Rust, mill scale and existing coatings are evaluated against the specified cleanliness standard. Visual cleanliness and surface profile are separate properties; a visually clean surface can have unsuitable roughness.

Profile provides mechanical anchoring but must suit the coating system. Too little profile can impair adhesion; excessive peaks can be inadequately covered. Measure with the approved method and account for instrument or replica-media characteristics. Do not treat a comparator grade and a numerical profile value as interchangeable without the method's basis.

Soluble salts can remain on a visually clean surface and contribute to osmotic blistering or underfilm corrosion. Use the specified sampling/extraction method, area and acceptance units. A fictional result of 8 micrograms/cm² cannot be compared directly to a limit stated in mg/m² without conversion: 1 microgram/cm² equals 10 mg/m², so the result is 80 mg/m². The project's actual limit must be supplied.

Practical assessment uses prepared training panels, known profile references and a supplied salt-test data set. The learner records location, method, calibration/checks and results, then applies the supplied criteria. Passing requires correct unit conversion and recognition that visible cleanliness does not prove salt absence. Actual abrasive work needs its exposure and containment controls.`,[
['Visual cleanliness and surface profile are:','Separate properties requiring the specified evaluations.','Always identical measures.','Both established by color alone.','Unrelated to coating performance.','A surface can meet a visual grade while having an unsuitable profile.'],
['8 micrograms/cm² equals:','80 mg/m²','0.8 mg/m²','8 mg/m²','8000 mg/m²','The area conversion yields 1 microgram/cm² = 10 mg/m².'],
['Why address oil before abrasive blasting?','To avoid spreading or embedding contamination during preparation.','Blasting always destroys every contaminant.','Oil improves primer adhesion.','Only color changes matter.','Preparation sequence affects whether a genuinely suitable substrate is produced.']]],
['Ambient conditions, dew point and application windows',`Air temperature, relative humidity, surface temperature and dew point interact. Condensation becomes possible when the surface approaches or falls below the dew point. The substrate can be colder than the surrounding air, especially after overnight cooling or when connected to cold service. Measure the actual surface, not merely ambient air near the inspector.

The required surface-to-dew-point margin comes from the coating specification and product instructions. For a fictional project requiring at least 3°C margin, surface temperature 18°C and dew point 16°C give only 2°C; application is held. At surface 20°C and the same dew point, the margin is 4°C, but other temperature/humidity limits still need checking. The 3°C example is supplied for the exercise, not a universal rule for every coating.

Conditions change during the shift and across the structure. Record time, location and instrument identity; increase monitoring when weather changes or work moves to a shaded/cold region. A morning acceptable reading does not prove the entire day's conditions. Rain, fog or condensation can affect prepared surfaces and partially cured coatings.

Practical assessment requires measuring a training surface and interpreting a time series with falling surface temperature. The learner identifies the point at which the supplied margin fails and the affected work window. The assessor checks actual measurements, arithmetic and hold/release communication. Backfilling environmental logs from a weather app is a critical failure.`,[
['Surface 18°C, dew point 16°C and required margin 3°C gives:','A failed 2°C margin.','A passing 3°C margin.','A passing 34°C margin.','No relevant calculation.','18−16 = 2°C, below the supplied requirement.'],
['Why measure substrate temperature directly?','It can differ materially from ambient air temperature.','Air and steel temperatures are always equal.','Surface temperature never affects cure.','Only humidity matters.','Thermal history and service conditions can make the substrate colder or hotter than air.'],
['A morning reading was acceptable but fog arrives later. What follows?','Recheck conditions and evaluate the affected application period.','Use the morning reading for the whole day.','Delete the fog observation.','Assume thicker coating prevents condensation.','Changing conditions can invalidate the previously acceptable application window.']]],
['Mixing, wet-film thickness and cure',`Multi-component coatings require the correct components, ratio, mixing and any specified induction time. Pot life is the usable period under stated conditions; it is affected by temperature and batch size and is not the same as dry-to-touch time. Adding unauthorized thinner to extend pot life changes the system and does not restart the chemical reaction clock.

For an idealized unthinned coating with 60% volume solids, dry-film thickness is approximately wet-film thickness times 0.60. To target 180 micrometres dry, the theoretical wet film is 180/0.60 = 300 micrometres. Real application losses, roughness and measurement methods affect results; thinning changes the solids relationship. Use the product's actual instructions and specification.

Observe stripe coats, edges, welds and difficult geometry where thin spots can occur. Excessively heavy application can cause sagging, solvent entrapment or cure problems. Recoat windows include minimum and maximum times and may require surface preparation when exceeded. A coating dry to touch may not be cured for immersion or chemical exposure.

Assessment uses labeled mock components, a mixing record and wet-film readings. The learner computes the target wet film, identifies a ratio error and decides what to do with a batch beyond the supplied pot life. A qualified assessor checks timing and traceability. The exercise never authorizes improvising ratios, solvents or cure schedules.`,[
['At 60% volume solids, 180 micrometres target dry film needs theoretical wet film of:','300 micrometres','108 micrometres','180 micrometres','600 micrometres','180/0.60 = 300 micrometres before real-world adjustments.'],
['Can unauthorized thinner restart expired pot life?','No; it does not reverse the curing reaction.','Yes, in every coating.','Yes, if viscosity looks normal.','Yes, if the color remains unchanged.','Chemical cure continues; appearance is not proof of usable material.'],
['Dry to touch means ready for immersion:','Not necessarily; service cure requirements must be met.','Always true.','True if film thickness is high.','True if the inspector touches it twice.','Handling dryness and full service cure are different states.']]],
['DFT, adhesion, holidays and defect diagnosis',`Dry-film-thickness measurement requires the appropriate instrument for the substrate and coating, calibration/verification and adjustment under the specified method. Roughness, curvature, edges and substrate properties can affect readings. Follow the project sampling and acceptance rule; a single favorable reading cannot establish an entire area's compliance. Do not average local severe under-thickness away unless the governing method explicitly permits the evaluated result.

For a fictional training area, readings 160, 180 and 200 micrometres average 180 micrometres. That average alone does not prove acceptance if the supplied criterion also requires every reading to be at least 170. Both the average and individual constraints must be applied. Real standards may define spot and area measurements differently.

Adhesion testing can be destructive and must use the approved method, location and repair plan. Holiday testing detects discontinuities through a suitable coating with a method appropriate to its type/thickness. High-voltage settings are not selected by intuition. Blistering, pinholes, cracking, runs and delamination suggest different causes; document evidence before assigning blame.

Practical assessment uses coated panels and supplied criteria. The learner verifies the gauge, takes a reproducible pattern, computes results and reports a planted local thin area. The assessor checks instrument use and disposition independently. Falsifying readings or increasing voltage until a desired result appears is a critical failure.`,[
['160, 180 and 200 micrometres average:','180 micrometres','170 micrometres','200 micrometres','540 micrometres','The sum is 540; divide by three to obtain 180.'],
['The average passes but one reading is below a separately required minimum. Result is:','Nonconforming under that supplied combined criterion.','Automatically acceptable because averages override all limits.','Acceptable if the lowest reading is deleted.','Unrelated to the specification.','Every applicable criterion must be met, not just the average.'],
['What must accompany a destructive adhesion test?','An approved method, location and restoration/repair plan.','Only an invoice.','A claim that coatings cannot be damaged.','No documentation if the test passes.','The test itself can damage the system and requires controlled restoration.']]],
['Coating inspection dossier and practical acceptance',`A coating dossier should tell the story of the applied system: specification and product revisions, batch identities, substrate condition, preparation, profile/salt checks, environmental logs, mixing/application records, thickness, cure, defects, repairs and final tests. Link readings to actual areas and dates. An inspector's final signature cannot create evidence for an unobserved preparation stage.

Capstone: a tank lining has acceptable average DFT, one below-minimum spot, missing surface-salt results and an early proposed immersion date. These are separate issues. Extra topcoat might address thickness through an approved repair but does not establish original cleanliness or adequate cure. The learner prepares a nonconformance and a technically bounded request for disposition.

The practical rubric uses at least two panels, a supplied specification and calibrated instruments. Assess preparation evaluation, environmental readings, mixing/WFT arithmetic, DFT pattern, defect reporting and repair verification. All domains must pass, with evidence retained by panel/area identity. Unsafe chemical use, invented logs or release despite a known critical specification failure requires reassessment.

AMPP inspector levels and supervision expectations depend on qualification, experience and project complexity. This course does not confer AMPP certification or authorize a basic inspector to accept complex lining work independently. The employer must establish appropriate technical supervision, actual credential status and project-specific authority.`,[
['Can extra topcoat prove missing original salt cleanliness?','No; underlying preparation evidence remains unresolved.','Yes, if the color is uniform.','Yes, if average DFT doubles.','Yes, after the invoice is paid.','Adding film cannot establish or remove undocumented substrate contamination by itself.'],
['Why link readings to actual areas and dates?','To establish what condition and application stage the evidence represents.','Only to make the report longer.','To replace instrument verification.','To avoid recording batch numbers.','Coating conditions vary by location and time, so traceability is essential.'],
['Does this course authorize independent acceptance of every AMPP project level?','No; actual credential, experience, supervision and authority must be established.','Yes, after a perfect quiz score.','Yes, for all tank linings.','Yes, if the inspector owns a gauge.','Knowledge training does not confer external certification or unrestricted technical authority.']]]
],[AMPP],['Six coating-specific lessons with salt-unit conversion, dew-point margin, WFT/DFT calculations, instrument exercises and practical rubric.'],['Actual product sheets/specifications, licensed preparation/measurement standards, current level-specific AMPP exam mapping and observed field practical delivery remain required.']);

add('OG46',[
['Damage-mechanism reasoning and evidence structure',`A damage mechanism is a physical or chemical process that degrades material; a damage morphology is the form it leaves, such as general thinning, pits, cracks, blisters or distortion. Similar morphology can have different causes. Diagnosis requires material, environment, temperature, stress, time and operating history. Do not identify a mechanism from a photograph alone when decisive service information is missing.

Create a mechanism worksheet with susceptible materials, necessary conditions, likely locations, expected appearance, inspection approach and mitigation. Include startup, shutdown, cleaning and upset conditions. Normal operating averages can conceal short excursions that initiate cracking or accelerated corrosion. Record both supporting and contradictory evidence so the hypothesis can be tested.

Case: carbon-steel piping has local thinning downstream of an injection point. Possible contributors include locally aggressive chemistry, turbulence and deposits. The location supports targeted investigation but does not prove one mechanism. Obtain fluid chemistry, injection design/history, thickness mapping and surface evidence. A generic corrosion-rate average may conceal the local severity.

Assessment requires two competing hypotheses and a plan that discriminates between them. The assessor checks whether the proposed method can detect the expected morphology and whether mitigation addresses the cause. Passing work avoids claiming that thicker replacement metal alone eliminates a continuing mechanism. This framework is applied in the following lessons to selected important mechanisms; it is not an exhaustive reproduction of API RP 571.`,[
['A photograph of pits alone establishes:','Morphology, but not necessarily the unique causal mechanism.','Exact process chemistry.','The complete operating history.','A universal remaining life.','Several mechanisms can produce localized loss; context is needed.'],
['Why include startup and shutdown history?','Transient conditions may initiate or accelerate damage absent during normal operation.','Only average temperature matters.','Transient records are never useful.','Damage stops whenever production stops.','Mechanisms can depend on excursions, wetting or thermal cycling.'],
['Replacing corroded material with thicker identical material necessarily eliminates the mechanism:','False; the damaging environment may continue.','True in every service.','True if painted externally.','True after an inspection report is signed.','More margin is not the same as removing the cause.']]],
['Aqueous corrosion, localized attack and CUI',`Aqueous corrosion involves electrochemical reactions where an electrolyte is present. Carbon steel may lose metal relatively uniformly or experience localized attack when chemistry, deposits, oxygen availability or flow varies. CO2 in water can form an acidic environment; corrosion behavior depends on water chemistry, temperature, flow and protective-scale stability, not CO2 presence alone. Microbiologically influenced corrosion requires evidence of microbial contribution and relevant conditions; unusual pits alone are not proof.

Galvanic corrosion requires electrically connected dissimilar electrochemical behavior and an electrolyte. Area ratio matters: a small anodic area coupled to a large cathodic area can suffer concentrated attack. Isolation, material selection and environmental control may be relevant mitigations, but actual design must consider the whole system.

Corrosion under insulation occurs when water reaches susceptible metal beneath insulation. Damaged weather barriers, supports, penetrations and intermittent service are important inspection locations. On austenitic stainless steel, wet chloride contamination can raise a different concern: chloride stress-corrosion cracking rather than simply carbon-steel-style wall loss. Material identity changes the hypothesis and inspection method.

Exercise: compare insulated carbon steel and insulated stainless steel at a leaking penetration. The learner proposes thickness mapping for loss and appropriate crack-sensitive examination when cracking is credible, with access and surface preparation addressed. The assessor rejects one universal UT thickness grid as proof against every mechanism. Mitigation includes correcting water ingress and insulation design, not only replacing the visibly damaged patch.`,[
['Galvanic corrosion requires:','An electrochemical difference, electrical connection and electrolyte.','Only different paint colors.','Only dry metal contact in every case.','Only a high-temperature furnace.','The galvanic cell needs both electronic and ionic paths.'],
['Why can a small anode with a large cathode be concerning?','Anodic current can concentrate on a small area.','The anode automatically becomes immune.','Area ratio never matters.','The cathode must always corrode faster.','The area relationship can intensify local anodic metal loss.'],
['Insulated stainless steel exposed to wet chlorides may require which additional concern?','Stress-corrosion cracking assessment.','Only a carbon-steel uniform-loss calculation.','No inspection because stainless never corrodes.','Only paint adhesion testing.','Stainless alloys can be susceptible to chloride-related cracking under appropriate conditions.']]],
['Environment-assisted cracking and wet hydrogen damage',`Stress-corrosion cracking requires a susceptible material, a specific environment and tensile stress. Residual welding stress can be sufficient even when applied stress seems modest. Chloride cracking in susceptible stainless steels, caustic cracking and amine-related cracking are different systems; their material and environmental conditions must not be collapsed into one generic limit.

Wet H2S environments can introduce hydrogen into steel. Hydrogen blistering and hydrogen-induced cracking may develop in susceptible material; stress-oriented hydrogen-induced cracking involves stress-related arrays. Sulfide stress cracking is associated with susceptible strength/hardness and tensile stress in the relevant environment. These mechanisms differ in morphology and controlling factors. A wall-thickness survey alone cannot rule out embedded or surface-connected cracking.

Mitigation may involve material selection, hardness/welding controls, process chemistry and reduction of harmful environments, under the applicable engineering standards. Do not invent a universal safe hardness, pH or temperature from a short lesson. Inspection selection must consider orientation, depth, accessibility and the specific mechanism, often combining methods.

Case: a weld-adjacent indication appears in wet sour service after a procedure change. The learner reviews material, hardness/heat-treatment records, welding history, environment and stress rather than assigning the cause solely to H2S odor. The assessor requires a mechanism comparison and a justified examination plan. Critical failure is accepting the component because average wall thickness is adequate while credible cracking remains unresolved.`,[
['Which three elements are central to stress-corrosion cracking?','Susceptible material, specific environment and tensile stress.','Only pressure, paint and age.','Only low wall thickness.','Only a visible leak.','SCC depends on a material-environment-stress combination.'],
['Can adequate average wall thickness rule out hydrogen-related cracking?','No; cracking requires suitable examination and evaluation.','Yes, if thickness exceeds nominal.','Yes, if corrosion rate is low.','Yes, if the vessel is painted.','Crack morphology is not represented by a uniform-thinning average.'],
['Why review residual stress and weld history?','They can affect cracking susceptibility even at modest operating loads.','Residual stress disappears immediately after welding.','Weld history affects only appearance.','Only pressure-gauge readings matter.','Welding can introduce stress and susceptible local microstructures.']]],
['High-temperature mechanisms and metallurgical change',`High-temperature service can change both dimensions and material properties. Creep is time-dependent deformation under stress at elevated temperature; accumulated exposure and stress history matter. A short inspection at ambient temperature cannot reconstruct all creep damage. Bulging, dimensional change or cracking may be clues, but specialized assessment and material evidence can be necessary before visible deformation appears.

High-temperature oxidation and sulfidation remove or alter material through chemical reaction. Behavior depends on alloy composition, environment and temperature. A nominal alloy label may be insufficient where trace composition materially affects susceptibility. Positive material identification and verified certificates can support, but not replace, the complete materials evaluation.

High-temperature hydrogen attack is distinct from wet-H2S cracking. Under relevant temperature and hydrogen partial pressure, susceptible steels can suffer internal changes and fissuring. It cannot be ruled out by a routine thickness reading. Carburization, decarburization, embrittlement and other metallurgical changes also require mechanism-specific evidence. Actual operating envelopes and reference curves must come from the authorized technical basis.

Exercise: compare a furnace component with long elevated-temperature exposure and a wet sour separator at lower temperature. Identify why different mechanisms, records and methods are needed. The assessor requires explicit distinction between hydrogen partial pressure and total pressure and between internal metallurgical damage and ordinary wall thinning. No generic temperature threshold is invented for acceptance.`,[
['Creep depends importantly on:','Stress, temperature and exposure time.','Only external paint condition.','Only the last hydrotest pressure.','Only room-temperature thickness.','Creep is time-dependent deformation under relevant elevated-temperature stress.'],
['High-temperature hydrogen attack and wet-H2S cracking are:','Different mechanisms requiring different evaluations.','Identical names for uniform corrosion.','Always detected by a single thickness point.','Prevented by any coating.','Their environments, physics and inspection strategies differ.'],
['Why distinguish hydrogen partial pressure from total pressure?','Hydrogen exposure depends on its contribution to the gas mixture pressure.','They are always numerically identical.','Partial pressure has no physical meaning.','Only gauge color determines susceptibility.','A mixed gas’s total pressure does not directly state the hydrogen component pressure.']]],
['Mechanical damage, fatigue and brittle fracture',`Fatigue develops under cyclic stress and may occur below a material's static strength. Sources include pressure cycles, vibration, thermal gradients and mechanical loading. Count and characterize cycles rather than relying only on peak pressure. Small-bore connections, attachments and geometric stress concentrations deserve attention. Once cracking exists, a uniform-corrosion remaining-life equation is inappropriate.

Thermal fatigue occurs when repeated temperature differences generate cyclic strain, especially at mixing points or intermittent quenching. Mechanical fatigue from vibration may concentrate near supports or branch connections. Erosion and erosion-corrosion involve flow and particles or interaction with corrosion films; localized thinning at elbows or impingement zones should be mapped rather than diluted into a line average.

Brittle fracture depends on toughness, temperature, stress and flaws. A material can fail with little gross deformation under unfavorable conditions. Low-temperature service changes and tests require review of material and fracture resistance, not an assumption that high tensile strength means high toughness.

For an educational cycle count, a valve event occurring 12 times/day over 300 operating days contributes 3600 events/year. If one event contains two significant thermal transients, the analyst must define what counts as a cycle before using the number. Assessment requires a cycle-history worksheet, susceptible-location sketch and inspection rationale. The assessor rejects a conclusion based solely on static design pressure or an unsupported fatigue-life prediction.`,[
['12 events/day over 300 days equals:','3600 events/year','25 events/year','360 events/year','3000 events/year','Multiply the event frequency by operating days; defining actual stress cycles remains separate.'],
['Why can a component fatigue below static strength?','Repeated stress cycles can initiate and grow cracks.','Static strength is always zero.','Fatigue requires corrosion in every case.','Only overload causes cracking.','Cyclic damage is not bounded solely by one static strength comparison.'],
['Does high tensile strength alone prove high fracture toughness?','No; they are different material properties.','Yes, universally.','Yes, if wall thickness is large.','Yes, after painting.','Strength and resistance to crack propagation are distinct.']]],
['Mechanism-based inspection and mitigation capstone',`Combine process, materials, inspection and engineering expertise in a damage-mechanism review. Document credible mechanisms, excluded mechanisms with reasons, susceptible locations, inspection effectiveness and operating limits. Exclusion requires evidence; absence of previous failures is not proof that a mechanism cannot occur. Revisit the review after feed changes, operating excursions, repairs or unexpected findings.

Capstone compares three assets: an insulated carbon-steel line with wet cladding, a stainless mixing tee with thermal cycles and chlorides, and a hot hydrogen-service vessel with incomplete history. The first needs external loss investigation and water-ingress correction; the second needs evaluation of thermal fatigue and environment-assisted cracking; the third requires a qualified high-temperature hydrogen assessment. A universal thickness-only plan is inadequate.

Mitigation should target mechanism drivers. Changing chemistry, material, temperature, water ingress or stress can reduce susceptibility, but each change needs controlled engineering review. Inspection reduces uncertainty and can detect developing damage; it does not physically remove the corrosive environment. Assign actions, owners, completion evidence and reassessment triggers.

Assessment requires three complete mechanism worksheets, two alternative hypotheses for an ambiguous indication and a prioritized inspection/mitigation plan. Score material/environment reasoning, morphology, method suitability, uncertainty and change control. All must pass. This course teaches selected major mechanisms in substantive detail; the API 571 BOK encompasses the entire referenced RP, so full mechanism-by-mechanism licensed study remains a separate documented gap.`,[
['Does inspection itself remove a corrosive environment?','No; it supplies information, while mitigation changes the drivers or condition.','Yes, by measuring wall thickness.','Yes, if the result is negative.','Yes, if performed annually.','Information and physical risk reduction are related but distinct.'],
['What should trigger a damage-mechanism review update?','Changed feed, excursions, repairs or unexpected findings.','Only a new report template.','Only a change in inspector signature style.','Never after the first review.','Mechanism assumptions depend on service and asset condition.'],
['An excluded mechanism should have:','A documented technical rationale and supporting evidence.','Only the phrase never happened before.','No record.','A favorable color on a matrix.','Exclusions must be defensible, particularly after changed conditions.']]]
],[API+'api571','https://www.api.org/-/media/Files/Certification/ICP/ICP-Certification-Programs/571_577_580/571_BOK_2024_final.pdf'],['Six lessons addressing mechanism reasoning, aqueous/CUI, environmental cracking, high-temperature, mechanical damage and integrated mitigation.'],['API 571 current public BOK points to the entire RP; this course does not cover every named mechanism, material-specific temperature window or licensed reference curve. Full exam equivalence is not claimed.']);

add('OG47',[
['RBI scope, decision criteria and team',`Risk-based inspection allocates inspection effort using the likelihood and consequences of loss of containment or other defined failure. Start with the decision: which equipment, failure modes, time horizon and risk criteria are included? State whether the study supports prioritization, inspection planning or a proposed interval change. An RBI label does not override legal or code requirements.

The team needs operations, inspection, corrosion/materials, process and engineering knowledge appropriate to the assets. Define who owns data, performs analysis, validates assumptions and accepts residual risk. A software user alone cannot supply all missing technical judgments. Record methodology/version and whether the approach is qualitative, semi-quantitative or quantitative.

Define tolerability and escalation before ranking equipment. Otherwise the team may move thresholds to fit a desired outage date. Distinguish financial, safety and environmental consequences; a monetary average must not conceal an unacceptable severe scenario. Scope exclusions, such as external impact or control-system failures, must be explicit and managed elsewhere.

Exercise: define an RBI study for ten process vessels with one high-consequence toxic service. The learner writes scope, criteria, team roles and exclusions. The assessor checks that an interval-extension decision has the necessary authority and that excluded hazards are not called safe. A passing charter gives the analysis a clear decision boundary rather than promising that every asset will receive a longer interval.`,[
['What should be established before ranking assets?','Scope, risk criteria, methodology and decision authority.','The desired interval extension for every asset.','Only a software license.','Only equipment purchase price.','Predefined criteria prevent outcome-driven manipulation of rankings.'],
['Can RBI automatically override legal inspection requirements?','No; applicable legal and code constraints remain.','Yes, whenever software gives low risk.','Yes, if the team is large.','Yes, if costs are high.','RBI operates within applicable mandatory requirements.'],
['A hazard excluded from the RBI model is:','Outside this analysis and must be explicitly managed elsewhere.','Proven safe.','Assigned zero probability automatically.','Removed from the plant.','Scope exclusion is not a risk assessment conclusion.']]],
['Data quality and damage review',`RBI inputs include equipment design, materials, service history, process chemistry, operating limits, inspection results, repairs and failure experience. Assess completeness, accuracy, relevance and age separately. A complete spreadsheet can contain unreliable values. Preserve source documents and assumptions so the model can be independently reviewed.

Damage-mechanism review links conditions to credible failure modes. Uniform thinning, localized loss and cracking require different probability models and inspection effectiveness assumptions. Historic thickness data from a benign upper shell cannot characterize a wet lower shell without justification. A process change can make old corrosion rates unrepresentative.

Use an uncertainty register. For each missing input, state plausible range, risk sensitivity and a plan to improve it. Do not fill unknown material or corrosion rates with a convenient low-risk default. Conservative assumptions can support interim prioritization, but they must remain visible and subject to review.

Case: two vessels have identical dimensions, but one has verified recent inspections and the other has an unexamined support and uncertain chemistry. Their information quality differs even if a default model gives the same nominal risk. The learner proposes targeted data collection and explains how the result could change ranking. The assessor requires traceable inputs and a clear distinction between measured facts, inferred values and assumptions.`,[
['A complete input spreadsheet proves:','Completeness of fields, not necessarily accuracy or relevance.','Every assumption is correct.','Every mechanism is absent.','The model needs no review.','Data quality has multiple dimensions beyond filled cells.'],
['How should an unknown corrosion rate be handled?','Use a justified explicit assumption/range and a plan to reduce uncertainty.','Enter zero without explanation.','Copy the lowest rate in the plant.','Hide the missing field.','Unknown inputs require transparent treatment and sensitivity assessment.'],
['Why may old thickness trends become unsuitable?','Process or damage conditions may have changed.','Measurements always become false after one year.','Only the software version matters.','Corrosion rates cannot change.','Historical rates are conditional on comparable service and measurement conditions.']]],
['Probability, inspection effectiveness and time',`Probability of failure describes the chance of a defined event over a stated period; failure frequency has units such as events/year. Do not mix the two without a model. For a constant-rate educational Poisson model, probability of at least one event over time t is 1−exp(−lambda*t). With lambda = 0.01/year and t = 5 years, probability is about 4.88%, not exactly 5% although the small-value approximation is close.

Probability models may use damage factors, condition, uncertainty and management-system assumptions. The chosen methodology determines their meaning. API 580 describes program elements; it should not be confused with a universal numerical equation set. A proprietary model output needs its assumptions and validation, not blind acceptance.

Inspection can improve knowledge of condition and support intervention. It does not make existing metal loss disappear. Effectiveness depends on the mechanism, method, coverage, detection capability and execution quality. A thickness spot-check may be useful for general loss but weak for a narrow crack. Negative findings must be interpreted with detection limitations.

Assessment: calculate the five-year probability and compare a crack-sensitive inspection with an irrelevant thickness-only check. The learner explains why a low-effectiveness inspection should not earn the same model credit. The assessor checks units, time horizon and the difference between improved information and physical repair.`,[
['At constant lambda=0.01/year over five years, 1−exp(−0.05) is approximately:','4.88%','50%','0.05%','99%','The exponential model gives 0.0488; the period and model must be stated.'],
['Inspection physically removes existing wall loss:','False; it informs condition and intervention decisions.','True for every UT inspection.','True if no indications are found.','True if the report is approved.','Measurement changes knowledge, not material condition.'],
['Inspection effectiveness depends on:','Mechanism, technique, coverage and execution capability.','Only the number of pages in the report.','Only instrument price.','Only inspector travel distance.','Detection capability must match the actual damage morphology and location.']]],
['Consequence models and risk calculations',`Consequence analysis asks what happens after the defined failure. Consider inventory, release size/rate, fluid phase, toxicity/flammability, pressure, isolation, detection, ignition, occupancy, environmental receptors and business interruption. A small leak in a toxic service can have different significance from a larger benign-fluid leak. Safeguards need credible availability and response assumptions.

For a simplified financial example, asset A has annual failure probability 0.02 and conditional loss of $100000, giving expected annual loss $2000. Asset B has probability 0.002 and conditional loss $2000000, giving $4000. B has lower probability but higher expected monetary loss. This arithmetic does not establish safety tolerability or capture the full consequence distribution.

Multiple scenarios may be needed: small leak, large release and rupture can have different probabilities and effects. Avoid double-counting overlapping events. If an isolation system is credited, specify detection delay, valve closure, available inventory and failure modes. A checklist saying automatic isolation exists is not performance evidence.

Assessment provides two release scenarios and a failed isolation assumption. The learner recalculates the supplied expected losses, identifies the omitted human/environmental consequence and documents sensitivity to delayed isolation. The assessor rejects a single financial number used to dismiss a severe scenario outside acceptance criteria. Consequence reasoning must remain traceable to the actual scenario and assumptions.`,[
['0.02 annual probability times $100000 conditional loss gives:','$2000 expected annual loss','$2000000 expected annual loss','$5000 expected annual loss','$20 expected annual loss','Multiply probability by conditional monetary consequence for this simple model.'],
['Which has higher expected monetary loss: A=$2000/year or B=$4000/year?','B, despite its lower probability in the example.','A because probability alone controls risk.','They are equal.','Neither can be compared arithmetically.','Risk combines likelihood and consequence; low probability alone does not mean low expected loss.'],
['Crediting automatic isolation requires:','A justified response/availability basis for the actual scenario.','Only the presence of a valve symbol.','Only a maintenance budget.','Only a favorable software default.','The consequence reduction depends on whether and when isolation actually functions.']]],
['Inspection plans and risk-reduction choices',`Translate a risk result into an actionable inspection plan: equipment/location, mechanism, technique, coverage, timing, preparation, required effectiveness, responsible role and response to findings. A priority number alone is not a plan. Identify the evidence needed to reassess risk after inspection and who will disposition unexpected results.

Inspection is one option among several. Repair, replacement, material upgrade, chemistry control, lower operating severity, improved isolation or inventory reduction may address risk more directly. If a mechanism cannot be detected reliably before failure, simply increasing inspection frequency may be ineffective. The team must evaluate physical mitigation and operating controls.

For a fictional decision, inspection costs $10000 and is expected to reduce uncertainty but not current damage; replacement costs $80000 and removes the damaged component while leaving the corrosive environment unchanged. Compare both over the stated horizon, including downtime and residual risk. Do not claim inspection produces the same physical benefit as replacement or replacement eliminates the mechanism forever.

Assessment requires a plan for a high-risk localized-corrosion location and a low-detectability cracking scenario. The learner specifies technique/coverage and an alternative mitigation for the latter. The assessor checks that timing follows risk criteria and mandatory limits, and that findings trigger predefined actions rather than an automatic pass.`,[
['A risk ranking becomes an inspection plan when it specifies:','Where, how, when, coverage, responsibilities and response criteria.','Only a red or green color.','Only an annual budget.','Only an equipment nickname.','Actionable plans translate risk into executable and reviewable work.'],
['If damage is poorly detectable before failure, the team should:','Evaluate physical mitigation and operating changes, not only more frequent weak inspections.','Assume frequency guarantees detection.','Reduce coverage to save time.','Set the probability to zero.','An ineffective method does not become reliable merely through repetition.'],
['Replacement with identical material necessarily removes the corrosive environment:','False; mechanism drivers may remain.','True in every process.','True after a pressure test.','True after an RBI report.','Replacement resets component condition but may leave the same degradation cause.']]],
['Reassessment, documentation and RBI capstone',`RBI is maintained through reassessment. Triggers include new inspection findings, process changes, excursions, repairs, failures, new mechanism knowledge and elapsed review dates. Track whether actual work matched the plan; planned inspection effectiveness cannot be credited when access or technique was reduced in the field. Management of change must reach the RBI assumptions, not stop at operating procedures.

Documentation should permit another qualified team to reproduce the decision: scope, team, method/version, input sources, mechanisms, probability and consequence assumptions, uncertainty, risk criteria, plans, accepted residual risk and review triggers. Preserve revisions and the reason for changed rankings. Software outputs without inputs or model version are insufficient.

Capstone: a low-risk vessel changes to wetter service, misses part of its planned inspection and experiences an upset. The learner invalidates the affected assumptions, identifies immediate technical review and updates the inspection/mitigation plan. Reusing the previous green ranking without review is unacceptable.

The assessor scores scope discipline, data traceability, mechanism reasoning, quantitative accuracy, uncertainty and actionable planning. All must pass; invented data, hidden exclusions or unsupported interval extensions are critical failures. API's 2026 public BOK references RP 580 fourth edition with Addendum 1; this original course teaches the core workflow and examples but does not reproduce the licensed document or prove complete examination coverage.`,[
['Planned coverage was reduced in the field. What happens to RBI inspection credit?','Reassess using actual effectiveness and coverage.','Keep full planned credit automatically.','Delete the limitation.','Assume access limitations improve reliability.','The model must reflect performed work, not intentions.'],
['A process change affects water content. Which record needs review?','Damage and RBI assumptions as well as operating documentation.','Only the product label.','Only payroll records.','No record if pressure is unchanged.','Chemistry changes can alter damage probability even at unchanged pressure.'],
['A reproducible RBI record includes:','Inputs, sources, method version, assumptions, criteria and decision history.','Only a final risk color.','Only a software screenshot.','Only an equipment count.','Another qualified team needs the reasoning and inputs behind the result.']]]
],[API+'api580','https://www.api.org/-/media/Files/Certification/ICP/ICP-Certification-Programs/571_577_580/2026/580_2026_BOK_final.pdf'],['Six lessons covering scope/team, data, POF, COF, inspection/mitigation and reassessment with probability and expected-loss cases.'],['Licensed API 580 clause-level coverage and methodology-specific quantitative equations are not supplied. Actual organization risk criteria, engineering validation and interval approval remain required.']);

add('OG48',[
['Prevention through design and system safety',`Professional safety practice begins by defining the system, lifecycle and people exposed. Procurement, design, installation, operation, maintenance and decommissioning create different hazards. Prevention through design seeks to remove hazards before work depends on warnings or perfect behavior. Elimination, substitution and engineered controls generally reduce dependence on individual action, but substitutes must be assessed for new hazards.

Use a task analysis to identify energy sources, exposure pathways and failure consequences. FMEA examines how components or functions can fail and their effects; a fault tree works backward from an unwanted event through combinations of causes. Neither is complete if the system boundary excludes maintenance or foreseeable misuse. Distinguish a barrier's existence from its effectiveness and independence.

In a simplified independent-barrier model, an initiating event frequency of 0.1/year and two independent failure probabilities of 0.1 each yield 0.001/year. The multiplication is invalid if both barriers depend on the same failed power supply or operator action. Common-cause failure must be examined rather than hidden behind small numbers.

Case: a pump seal leak threatens workers during sampling. Compare remote sampling, a redesigned closed system, ventilation and PPE. The learner explains which changes remove or isolate exposure and which rely on continuing behavior. Assessment requires a system boundary, hazard analysis and common-cause review. The assessor rejects multiplying dependent barriers or claiming substitution is automatically safer without evaluating its new chemistry and maintenance demands.`,[
['0.1/year times independent failure probabilities 0.1 and 0.1 gives:','0.001/year','0.3/year','0.01/year','1/year','Multiply the three factors only under the stated independence assumptions.'],
['Two barriers share one vulnerable power supply. What must be considered?','Common-cause failure and invalid independence credit.','Automatic doubling of protection.','No interaction between barriers.','Only the purchase price.','Shared dependencies can defeat both barriers together.'],
['A substitute chemical is safer solely because it is different:','False; new hazards and lifecycle effects must be evaluated.','True by definition.','True if cheaper.','True if supplied in a smaller container.','Substitution requires a comparative hazard assessment, not just a different name.']]],
['Program management, indicators and economic analysis',`A safety management program assigns responsibilities, resources, worker participation, hazard controls, training, evaluation and improvement. Translate policy into accountable actions with owners, due dates and evidence of effectiveness. A completed task is not necessarily an effective control. Closing a work order for ventilation installation must be followed by performance verification.

Use leading and lagging indicators together. Injury rates describe outcomes but can be unstable in small populations and influenced by reporting. Inspections completed is an activity measure; critical defects corrected within an appropriate time and verified control performance are closer to preventive effectiveness. Incentives that suppress reporting can make a dashboard improve while risk worsens.

For a supplied incident-rate exercise, four recordable cases in 400000 work hours produce (4×200000)/400000 = 2.0 cases per 100 full-time-equivalent workers under this conventional normalization. The result is not a probability that an individual will be injured. Compare like definitions and exposure periods, and examine severity and uncertainty.

A simple investment example has a $60000 control cost and $20000 annual net benefit, giving a three-year simple payback. Payback omits discounting, service life and severe-tail consequences and cannot waive mandatory controls. Assessment requires an indicator set, rate calculation and investment memo explaining assumptions. The assessor checks whether the proposed measures encourage reporting and verify control effectiveness rather than reward silence.`,[
['Four cases in 400000 hours using a 200000-hour base gives:','2.0','0.5','8.0','20.0','Multiply the four cases by the 200000-hour normalization base, then divide by 400000 hours worked: 4*200000/400000 = 2.0 cases per 200000 hours.'],
['$60000 cost and $20000 annual net benefit gives simple payback:','3 years','0.33 years','30 years','$40000','Cost divided by annual benefit is three years; this omits discounting and other factors.'],
['A falling injury count with suppressed reporting indicates:','Potential measurement distortion, not proof of lower risk.','Certain program success.','No need for worker feedback.','Automatic regulatory compliance.','Reporting behavior can change the observed metric without changing underlying hazards.']]],
['Occupational exposure, sampling and applied science',`Exposure assessment identifies the agent, route, task, population, duration and variability. Personal breathing-zone sampling addresses a worker's inhalation exposure differently from an area monitor. Choose a method capable of measuring the relevant fraction and concentration, with calibration, flow, duration, blanks and laboratory requirements. A nondetect is bounded by the method's detection limit and sampling conditions.

For a simple eight-hour time-weighted concentration, four hours at 40 ppm and four hours at 10 ppm give (4×40+4×10)/8 = 25 ppm. Compare only with the appropriate substance-specific limit and averaging period. A shift average does not rule out a short-term or ceiling exceedance. Mixed-agent effects and skin exposure may require additional assessment.

Noise uses logarithmic levels. Under the NIOSH recommended 85 dBA eight-hour criterion with a 3 dB exchange rate, 88 dBA corresponds to four hours and 91 dBA to two hours for equal energy. This is a recommended basis, distinct from OSHA's regulatory noise calculation. Do not mix exchange rates within one dose calculation.

Case: area monitoring is low but a worker's intermittent cleaning task creates a breathing-zone peak. The learner designs task-focused sampling and engineering controls instead of declaring the site safe from the area average. Assessment checks arithmetic, method selection, uncertainty and the hierarchy of controls. Respirator selection requires the actual hazard and respiratory-protection program.`,[
['Four hours at 40 ppm and four at 10 ppm yield an eight-hour average of:','25 ppm','50 ppm','30 ppm','15 ppm','The time-weighted sum is 200 ppm-hours divided by eight hours.'],
['Under the stated NIOSH 3 dB rule, 91 dBA corresponds to:','2 hours','8 hours','4 hours','16 hours','Two 3 dB increases from 85 halve eight hours twice.'],
['A low full-shift average excludes every short-term peak hazard:','False; short-term and ceiling conditions need separate evaluation.','True for every chemical.','True if an area monitor was used.','True if the worker wore gloves.','Different exposure limits and routes require different evidence.']]],
['Ergonomics, human factors and training design',`Ergonomics fits work to human capabilities rather than assuming every worker can compensate for poor design. Evaluate force, repetition, posture, duration, vibration, recovery and environmental conditions. A load's mass alone does not define manual-handling risk: reach distance, asymmetry, grip, frequency and travel path matter. Mechanical assistance can reduce lifting demand while introducing pinch, traffic or maintenance hazards that also need controls.

Human factors include workload, fatigue, interface design, task complexity and organizational pressure. A control panel with similar switches and ambiguous labels creates error opportunities. Training can improve recognition but cannot reliably compensate for an interface that makes a dangerous selection easy. Design distinct controls, clear feedback and recovery opportunities where feasible.

Training starts with a task/competency needs assessment. Define observable outcomes, teach the actual decision and provide practice with feedback. A quiz evaluates selected knowledge; a supervised demonstration evaluates performance under stated conditions. Attendance alone evaluates neither. Use understandable language, accessible materials and varied practice based on the task, without assuming a fixed learning-style label guarantees effectiveness.

Assessment: redesign a repetitive valve-handling task and create a short training plan. The learner identifies exposure factors, proposes engineering changes and defines an observed performance criterion. The assessor checks whether training outcomes map to actual hazards and whether post-training observations measure transfer to work. A perfect quiz cannot substitute for an unobserved critical manual skill.`,[
['Manual-handling risk depends on:','Mass plus reach, posture, frequency, grip and task conditions.','Mass alone in every case.','Only the worker’s job title.','Only training attendance.','Biomechanical demand changes with task geometry and repetition.'],
['A confusing control interface should primarily prompt:','Design review and error-reducing controls alongside appropriate training.','Only a reminder to be careful.','Punishment for every selection error.','Removal of all labels.','System design can create predictable errors that training alone cannot reliably prevent.'],
['Which evidence evaluates a critical manual skill?','Observed performance against defined criteria.','Attendance alone.','A course invoice.','A self-reported confidence score alone.','A practical skill must be demonstrated under relevant conditions.']]],
['Emergency, environmental and continuity planning',`Emergency planning starts with credible scenarios and the site's people, materials, geography and response capability. Define alarm, evacuation or shelter decisions, accountability, incident command, external coordination, medical access and recovery authority. A written plan must be practiced under realistic communication and access constraints. An exercise should test decisions and resources, not simply rehearse a familiar assembly point.

Environmental management connects material inventories, storage compatibility, releases, waste characterization, permits and disposal. A waste's identity and properties determine the applicable handling route; do not classify it solely by container color or origin. Spill prevention and secondary containment must address actual inventories and credible failure paths.

For an educational containment example, a rectangular basin 5 m by 4 m with 0.5 m usable depth has 10 m³ gross usable volume before displacement and required freeboard adjustments. If equipment displaces 2 m³, only 8 m³ remains. Whether this is sufficient depends on the governing rule, largest release scenario, precipitation and site design; there is no universal acceptance from this arithmetic alone.

Assessment combines a chemical release, power loss and blocked access route. The learner assigns response roles, identifies the safe protective action and calculates the supplied containment volume. The assessor checks response capability, communication redundancy, environmental pathways and criteria for reentry/restart. Untrained rescue or uncontrolled spill intervention is a critical failure.`,[
['A 5 m by 4 m basin with 0.5 m usable depth has gross volume:','10 m³','20 m³','2 m³','40 m³','Length*width*depth = 5*4*0.5 = 10 cubic metres.'],
['If equipment displaces 2 m³ from that volume, remaining volume is:','8 m³','12 m³','20 m³','5 m³','Displacement reduces available capacity; other design allowances still require review.'],
['A successful emergency drill should evaluate:','Decisions, communication, accountability and actual resource capability.','Only attendance at an assembly point.','Only how quickly a report is filed.','Only the number of printed plans.','Exercises test whether the plan functions under realistic constraints.']]],
['Professional ethics, investigation and integrated capstone',`A safety professional must communicate uncertainty and limitations honestly, protect confidential information and work within competence. Distinguish regulatory requirements, consensus standards, employer policy and professional recommendations. Determine applicability before citing a requirement, and obtain specialist input when the technical or legal question exceeds the available basis. Do not manipulate data to obtain a preferred business conclusion.

Incident investigation reconstructs events and conditions using evidence. Separate facts, witness accounts and hypotheses; preserve timelines, equipment state and records without altering the scene except for necessary response. Seek system contributors such as design, maintenance, workload and incentives rather than stopping at worker error. Corrective actions need an owner, due date and effectiveness verification.

Capstone: a contractor injury occurs during a changed maintenance task. Training was current, but isolation drawings were outdated, production pressure shortened planning and near misses were underreported. The learner proposes immediate controls, an evidence plan, causal analysis and durable corrective actions. Repeating the same training alone does not address the design and management failures.

The assessor scores technical reasoning, quantitative accuracy, source applicability, worker participation, ethical reporting and verification. All must pass. The current public CSP11 blueprint spans seven broad domains; these lessons and supporting bundles address substantial elements but do not establish full item-level coverage or BCSP eligibility. A VNDRLY completion record is an original knowledge achievement, not the CSP credential.`,[
['An investigation should distinguish:','Facts, witness accounts and hypotheses.','Only blame and punishment.','Only direct costs.','Only the final conclusion with no evidence.','Different evidence types have different certainty and need traceable treatment.'],
['Outdated isolation drawings contributed to an incident. Repeating training alone:','Does not correct the document/control-system failure.','Automatically fixes the drawings.','Eliminates the need for verification.','Proves the worker was solely responsible.','Corrective actions must address the demonstrated system causes.'],
['When a technical decision exceeds the professional’s competence or evidence, they should:','State the limit and obtain appropriate specialist input.','Invent a confident answer.','Hide uncertainty in a green dashboard.','Copy an unrelated legal requirement.','Professional judgment includes recognizing and communicating limits.']]]
],[BCSP+'certified-safety-professional-csp/','https://www.bcsp.org/hubfs/Website/Blueprints-References/CSP-Blueprint.pdf?hsLang=en','https://www.osha.gov/safety-management','https://www.cdc.gov/niosh/noise/prevent/understand.html'],['Six substantial professional-practice lessons spanning the seven CSP11 domains with independent-barrier, rate/payback, exposure/noise and containment calculations.'],['Complete CSP11 objective-by-objective coverage and broad scientific/legal examination preparation are not established. BCSP degree, qualifying credential, experience and examination are external requirements.']);

add('OG49',[
['Construction sequencing, site plans and simultaneous work',`Construction risk changes as the site changes. Map phases, temporary works, access routes, utilities, deliveries and interactions among trades. A safe layout during foundation work may become unsafe when steel erection, lifts and electrical commissioning overlap. The site-specific plan must describe actual means and methods, responsible parties and change triggers rather than copy a generic corporate manual.

Use a job hazard analysis to break work into meaningful steps, identify energy/exposure and select controls. Consider workers performing the task and others nearby. A crane exclusion zone that blocks the only emergency access route creates another hazard; coordinate the layout before execution. Prefer removal or separation of conflicting work over relying on workers to notice one another at the last moment.

Case: overhead pipe installation, mobile equipment travel and scaffold access share a narrow corridor. Sequence work, establish controlled routes and prevent people entering suspended-load areas. Clarify who authorizes changes and how crews learn about them. Signs alone do not physically separate an uncontrolled vehicle route.

Assessment requires a marked logistics plan and a daily coordination briefing for three trades. The assessor checks foreseeable interactions, emergency access, material storage, competent-person assignments and a method to revise the plan after changes. Critical failures include approving work beneath an uncontrolled suspended load or treating yesterday's inspection as proof of today's site conditions.`,[
['Why must construction safety plans change with project phases?','Work methods, temporary conditions and trade interactions change.','Only the project name changes.','Hazards always decrease over time.','One initial plan guarantees every later condition.','Construction creates evolving configurations and exposure paths.'],
['An exclusion zone blocks emergency access. What is required?','Coordinate a layout that controls both lifting exposure and emergency access.','Ignore access until an emergency occurs.','Remove all lifting controls.','Use a smaller sign only.','One control must not create an unmanaged critical hazard elsewhere.'],
['The strongest response to conflicting overhead and pedestrian work is often:','Separate or sequence the work with controlled access.','Tell pedestrians to watch carefully.','Rely only on hard hats.','Assume the crane operator sees everyone.','Physical/time separation reduces reliance on vigilance.']]],
['Falls, excavations and structural temporary conditions',`Fall prevention begins with suitable working surfaces, access and collective protection where feasible. Select the applicable standard for the activity; construction thresholds and requirements vary among general fall protection, scaffolds, steel erection and other scopes. A harness alone does not constitute a complete system. Anchorage, connectors, compatibility, clearance, swing-fall exposure and rescue must be addressed.

For a fictional clearance exercise, supplied components are 1.8 m free fall, 1.0 m deceleration, 0.3 m harness/D-ring movement, 1.5 m distance below the D-ring and 1.0 m safety allowance. Their sum is 5.6 m. This simplified example is not a manufacturer-approved design; actual equipment geometry, anchorage height and instructions govern. If available clearance is 4.8 m, the supplied arrangement cannot be accepted.

Excavations require assessment of soil, water, adjacent loads, utilities, access and protective systems by the designated competent person. Temporary forms, shoring and partially completed structures can have load paths unlike the completed design. Do not remove supports because concrete looks hard or a structure appears stable.

Practical assessment uses a safe ground-level fall-system mockup and excavation/temporary-work drawings. The learner identifies missing clearance or rescue information and a changed ground condition. The assessor requires correct arithmetic and referral to the actual design/manufacturer basis. No learner is exposed to a real fall or unprotected trench for assessment.`,[
['The supplied clearance components 1.8+1.0+0.3+1.5+1.0 total:','5.6 m','4.8 m','3.1 m','6.6 m','All supplied distances sum to 5.6 m; actual systems require their own approved calculation.'],
['Only 4.8 m is available for the supplied 5.6 m arrangement. Decision is:','Do not use that arrangement; obtain a suitable designed system.','Round down the requirement.','Ignore the safety allowance.','Assume the harness shortens the fall.','Available clearance is less than the stated need.'],
['Can temporary supports be removed because the structure looks stable?','No; the authorized structural/temporary-works basis governs.','Yes, visual appearance establishes capacity.','Yes, after a toolbox talk.','Yes, if no cracking is visible.','Temporary load paths and strength require the defined release criteria.']]],
['Lifting, equipment, electrical and stored-energy interfaces',`Mobile equipment creates struck-by, caught-between and rollover hazards. Separate pedestrian routes, manage reversing and blind spots, maintain stable travel surfaces and verify operator/equipment suitability. A spotter needs an agreed communication method and a safe position; a spotter is not a substitute for eliminating unnecessary people from the operating envelope.

Lifting requires an actual lift plan, configuration/load-chart review, ground support, rigging and communication. In a simplified symmetric two-leg sling model, tension per leg is W/(2 sin theta), where theta is the angle above horizontal. For a 1000 kg-force equivalent load and theta 30°, each leg carries 1000 kg-force; at 60°, each carries about 577 kg-force. This static model excludes dynamic effects, unequal loading and hardware limits and cannot select production rigging.

Electrical hazards include contact, arc energy and unexpected energization. Identify overhead/underground services and temporary power conditions. Isolation must address all energy sources and stored energy, with verification by the authorized process. An unplugged tool does not establish isolation of connected hydraulic or pneumatic equipment.

Assessment combines a lift sketch, pedestrian route and maintenance task. The learner calculates model sling tension, identifies power-line and pinch exposures and traces multiple energy sources. The assessor checks that the learner does not convert the simplified tension into a rated-capacity approval or treat a switch-off command as verified isolation.`,[
['For W=1000 kg-force and sling angle 30° above horizontal, ideal leg tension is:','1000 kg-force','500 kg-force','250 kg-force','2000 kg-force','1000/(2*sin30°) = 1000 kg-force per leg.'],
['Reducing sling angle toward horizontal generally:','Increases leg tension.','Decreases leg tension to zero.','Has no effect.','Eliminates hardware limits.','The sine in the denominator decreases, increasing tension.'],
['Turning off an electrical switch establishes all-energy isolation:','False; other sources and stored energy must be controlled and verified.','True for every machine.','True if a sign is attached.','True if the operator leaves.','Electrical command state is not complete physical energy isolation.']]],
['Construction health exposures and monitoring',`Construction health hazards include silica, welding fumes, lead/asbestos where present, noise, heat/cold, vibration and biological exposures. Identify materials before disturbance and select controls for the actual task. Dust appearance cannot establish respirable concentration or composition. Demolition coatings and insulation may require surveys and specialist controls before work begins.

For silica construction tasks, OSHA's specified-control route requires fully and properly implementing the applicable Table 1 controls and respiratory provisions, or using the alternative exposure-assessment route. Merely owning a vacuum or wet saw does not establish compliance if the configuration or operation differs from the required method. Actual task duration, indoor/outdoor conditions and equipment matter.

For a supplied exposure exercise, two hours at 100 micrograms/m³, four hours at 25 and two hours at 0 give an eight-hour average of (200+100)/8 = 37.5 micrograms/m³. Compare with the applicable limit and action requirements, while retaining task peaks and uncertainty. This arithmetic alone does not establish the entire silica program or substitute for valid sampling.

Assessment asks the learner to inspect a mock dust-control setup, identify missing capture/maintenance elements and develop a task-based sampling question. The assessor checks control selection, instrument purpose, respiratory-program boundaries and health-record privacy. Critical failures include dry disturbance of unidentified hazardous material or treating no visible dust as proof of no exposure.`,[
['2 h at 100, 4 h at 25 and 2 h at 0 micrograms/m³ yields:','37.5 micrograms/m³','125 micrograms/m³','62.5 micrograms/m³','25 micrograms/m³','The weighted total is 300 concentration-hours divided by eight.'],
['Owning a dust extractor proves the specified silica control is implemented:','False; configuration, operation and maintenance must match the requirement.','True regardless of filter or airflow.','True if the tool is new.','True if dust is not obvious.','Control performance depends on actual implementation, not ownership.'],
['Before disturbing unidentified old coatings or insulation, the plan should:','Establish material hazards and required controls.','Assume all old material is harmless.','Rely on color alone.','Begin work and sample only after complaints.','Material identification and exposure planning must precede potentially hazardous disturbance.']]],
['Emergency coordination and incident learning',`A construction emergency plan must fit changing site access, elevation, excavation, headcount and communication. Define how to report the emergency, provide precise location, summon appropriate help, evacuate or shelter and account for workers and visitors. Coordinate with external responders about access restrictions and site hazards before an incident. A public emergency number alone does not demonstrate rescue capability for a suspended worker or confined space.

Drills should test realistic failures: blocked gate, unavailable supervisor, radio dead zone or a subcontractor missing from the roster. Record the timeline and decisions, then correct the demonstrated gaps. Response speed is not the only measure; sending untrained people into danger can worsen the event. Medical information and injury details require appropriate confidentiality.

After immediate response, preserve evidence and investigate conditions. A dropped object may involve storage, toe boards, work sequencing, exclusion zones and supervision, not merely a worker's grip. Interview witnesses without leading them to a preferred conclusion. Separate what was observed from assumptions and identify why barriers failed.

Assessment uses a tabletop event with a blocked access route and an injured worker at height. The learner activates the correct response, protects others and tracks accountability without improvising a rescue. The assessor evaluates communication accuracy, role clarity, escalation and restart criteria. A corrective-action plan must name owners and verify effectiveness rather than close everything with a toolbox talk.`,[
['An emergency phone number alone proves technical rescue capability:','False; access, resources, competence and response arrangements must be established.','True for every site.','True if the number is printed in red.','True if workers have smartphones.','Rescue capability requires more than contact information.'],
['A drill reveals a radio dead zone. Closure requires:','A corrected communication arrangement verified under realistic conditions.','Only filing the drill report.','Only blaming the caller.','Deleting the dead-zone note.','Effectiveness must be demonstrated after the corrective action.'],
['A dropped-object investigation should examine:','Storage, barriers, sequencing and other system contributors as well as actions.','Only who last touched the object.','Only replacement cost.','Only whether the injured person wore a hard hat.','Multiple control and organizational conditions can contribute to the event.']]],
['Leadership, inspection records and CHST capstone',`Construction safety technicians influence work through credible field knowledge, clear communication and consistent follow-through. Explain the hazard and required control in language the crew understands, confirm understanding through demonstration or teach-back, and protect the ability to report concerns. A signed attendance sheet does not establish that a worker can perform a critical task.

Inspections should record location, condition, applicable requirement, immediate protection, assigned owner, due date and closure evidence. Prioritize by potential severity and exposure, not merely by how easy an item is to fix. A repeated defect suggests a system problem with procurement, maintenance, planning or supervision. Trend recurrence and verify that the correction persists.

Capstone: a site has good injury statistics but repeated missing edge protection, dust-control failures and late trade coordination. The learner builds a prioritized plan, defines immediate controls and assigns durable corrective actions. The absence of reported injuries does not justify continuing known hazardous conditions. Include a field demonstration and follow-up observation to verify training transfer.

The assessor scores hazard recognition, control selection, calculation accuracy, emergency coordination, documentation and communication. All domains must pass; hiding a critical finding, inventing an inspection or authorizing unsafe exposure is a critical failure. These lessons align broadly with the four public CHST5 domains but do not establish complete blueprint coverage, required experience or BCSP certification. Actual site authority and specialist qualifications remain separate.`,[
['Good injury statistics permit ignoring repeated missing edge protection:','False; known hazardous conditions require correction.','True until an injury occurs.','True if workers signed attendance sheets.','True if the project is almost complete.','Lagging statistics do not negate observed exposure to serious hazards.'],
['A repeated defect suggests the need to examine:','Underlying planning, procurement, maintenance or supervision causes.','Only a new warning sign.','Only the last worker observed.','Only report formatting.','Recurrence indicates that the system producing the condition may remain unchanged.'],
['Which record demonstrates corrective-action closure?','Evidence that the required control is in place and effective.','Only a promised completion date.','Only an assigned owner.','Only a green status label.','Assignment and intent are not observed completion or effectiveness.']]]
],[BCSP+'construction-health-and-safety-technician-chst/','https://www.bcsp.org/hubfs/Website/Blueprints-References/CHST-Blueprint.pdf?hsLang=en','https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.1153','https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.501'],['Six construction-practice lessons spanning CHST5 domains with logistics, clearance, sling-tension, exposure, emergency and leadership casework.'],['Complete CHST5 subobjective mapping, every construction specialty, site-specific plans and actual BCSP experience/examination are not established by this course.']);

